#define XASUFW_HSS_KAT_PUB_KEY_SIZE	(60U) /**< HSS KAT public key size in bytes */

/*
 * KAT vectors of an overlaid algorithm live in that algorithm's overlay data image rather than in
 * resident memory. Each vector is only read while its image is loaded, so it is present exactly
 * when it is needed. Naming the section explicitly is what routes it there: the resident .rodata
 * output section is defined ahead of the data overlay block and ends in a .rodata.* catch-all, so
 * a vector left under its default section name would be claimed by resident memory first. The
 * attribute also keeps these symbols out of the small-data area, which cannot reach the data
 * overlay window.
 */
#define XASUFW_KAT_MLDSA_DATA	__attribute__((section(".overlay_mldsa_data")))
					/**< Place a vector in the ML-DSA overlay data image */
#define XASUFW_KAT_MLKEM_DATA	__attribute__((section(".overlay_mlkem_data")))
					/**< Place a vector in the ML-KEM overlay data image */
#define XASUFW_KAT_LMS_DATA	__attribute__((section(".overlay_lms_data")))
					/**< Place a vector in the LMS overlay data image */
#define XASUFW_KAT_SLHDSA_DATA	__attribute__((section(".overlay_slhdsa_data")))
					/**< Place a vector in the SLH-DSA overlay data image */
#define XASUFW_KAT_RSAECC_DATA	__attribute__((section(".overlay_rsa_ecc_data")))
					/**< Place a vector in the RSA-ECC overlay data image */

