/*
 * FIPS Known-Answer-Test (KAT) vectors for the post-quantum algorithms ML-DSA (FIPS 204) and
 * ML-KEM (FIPS 203). The vectors are taken verbatim from the NIST ACVP server test data
 * (github.com/usnistgov/ACVP-Server, gen-val/json-files, internalProjection.json) and used to
 * satisfy the FIPS 140-3 IG 10.3.A Cryptographic Algorithm Self-Test (CAST) requirements. Per
 * IG 10.3.A the compared outputs are stored as a hashed representation (SHA-256 digest of the
 * expected output bytes) rather than the full output.
 *
 * Key generation has no CAST here. It is covered on every key generation request by the pairwise
 * consistency test built into XMldsa_KeyGen and XMlkem_KeyGen.
 *
 * Selected vectors:
 *   - ML-DSA-44 sigGen (ML-DSA-sigGen-FIPS204, tgId 1, tcId 7; deterministic, external/pure).
 *     The vector also carries pk, so sigVer is driven from the signature that sigGen just
 *     produced, so one vector covers both directions.
 *   - ML-KEM-512 encap (ML-KEM-encapDecap-FIPS203, tgId 1, tcId 1; AFT encapsulation). The vector
 *     also carries dk, so decaps is driven from the ciphertext that encaps just produced.
 */
