/*************************************************************************************************/
/**
 * @brief	This function executes KAT (Known Answer Test) for all cryptographic modules.
 *
 *************************************************************************************************/
void XAsufw_RunCryptoKats(void)
{
	s32 Status = XASUFW_FAILURE;
	XSha *XAsufw_Sha3Ptr = XSha_GetInstance(XASU_XSHA_1_DEVICE_ID);
	XTrng *XAsufw_TrngPtr = XTrng_GetInstance(XASU_XTRNG_0_DEVICE_ID);

	/** Get the DMA instance pointer. */
	XAsufw_Dma *AsuDmaPtr = XAsufw_GetDmaInstance(ASUDMA_0_DEVICE_ID);

	XAsufw_Printf(DEBUG_GENERAL, "Running KAT tasks\r\n");

	/** Run AES GCM mode KAT. */
	XAsufw_RunAesKats(AsuDmaPtr);

	/** Run KDF KAT and its dependent module KATs (HMAC, SHA2-256/512). */
	RunKdfAndDependentKat(AsuDmaPtr);

	/** Run SHA3-256 KAT. */
	Status = XAsufw_ShaKat(XAsufw_Sha3Ptr, AsuDmaPtr, XASUFW_SHA3, XASU_SHA_MODE_256);
	if (Status == XASUFW_SUCCESS) {
		/** On SHA3 KAT success, mark SHA3 module KAT as passed in RTCA area. */
		XASUFW_SET_KAT_PASSED(XASU_MODULE_SHA3_ID);
	}

	XAsufw_RunTrngKats(XAsufw_TrngPtr);

	/** Activate the RSA-ECC overlay once for the RSA KAT. */
	Status = XOverlay_Activate(XOVERLAY_ALGO_RSA_ECC, AsuDmaPtr);
	if (Status != XASUFW_SUCCESS) {
		/**
		 * On overlay activation failure, mark RSA, ECC and KEYWRAP module KATs as failed in
		 * RTCA area and disable the RSA, ECC and KEYWRAP resources.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_RSA_ID);
		XAsufw_DisableResource(XASUFW_RSA);
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_ECC_ID);
		XAsufw_DisableResource(XASUFW_ECC);
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_KEYWRAP_ID);
		XAsufw_DisableResource(XASUFW_KEYWRAP);
		XAsufw_DisableResource(XASUFW_OCP);
		XAsufw_DisableResource(XASUFW_ECIES);
	}
	else {
#ifdef XASU_RSA_PADDING_ENABLE
		XAsufw_RunRsaKats(AsuDmaPtr);
#endif /* XASU_RSA_PADDING_ENABLE */

		XAsufw_RunKeywrapKats();

		XAsufw_RunEccKats(AsuDmaPtr);
	}

#ifdef XASU_LMS_ENABLE
	/** Activate LMS overlay before running HSS KAT with SHAKE-256. */
	Status = XOverlay_Activate(XOVERLAY_ALGO_LMS, AsuDmaPtr);
	if (Status != XASUFW_SUCCESS) {
		/**
		 * On overlay activation failure, mark LMS module KAT as failed in RTCA area and
		 * disable the LMS resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_LMS_ID);
		XAsufw_DisableResource(XASUFW_LMS);
	}
	else {
		/** Run HSS KAT with SHAKE-256. */
		Status = XAsufw_HssOperationKat(AsuDmaPtr);
		if (Status == XASUFW_SUCCESS) {
			/** On HSS KAT success, mark LMS module KAT as passed in RTCA area. */
			XASUFW_SET_KAT_PASSED(XASU_MODULE_LMS_ID);
		}
	}
#endif /* XASU_LMS_ENABLE */

#ifdef XASU_MLDSA_ENABLE
	/** Activate ML-DSA overlay before running the ML-DSA-44 KAT. */
	Status = XOverlay_Activate(XOVERLAY_ALGO_MLDSA, AsuDmaPtr);
	if (Status != XASUFW_SUCCESS) {
		/**
		 * On overlay activation failure, mark ML-DSA module KAT as failed in RTCA area and
		 * disable the ML-DSA resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_MLDSA_ID);
		XAsufw_DisableResource(XASUFW_MLDSA);
	}
	else {
		/** Run ML-DSA-44 KAT (deterministic sigGen + sigVer against NIST ACVP vectors). */
		Status = XAsufw_MldsaOperationKat(AsuDmaPtr);
		if (Status == XASUFW_SUCCESS) {
			/** On ML-DSA KAT success, mark ML-DSA module KAT as passed in RTCA area. */
			XASUFW_SET_KAT_PASSED(XASU_MODULE_MLDSA_ID);
		}
	}
#endif /* XASU_MLDSA_ENABLE */

#ifdef XASU_MLKEM_ENABLE
	/** Activate ML-KEM overlay before running the ML-KEM-512 KAT. */
	Status = XOverlay_Activate(XOVERLAY_ALGO_MLKEM, AsuDmaPtr);
	if (Status != XASUFW_SUCCESS) {
		/**
		 * On overlay activation failure, mark ML-KEM module KAT as failed in RTCA area and
		 * disable the ML-KEM resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_MLKEM_ID);
		XAsufw_DisableResource(XASUFW_MLKEM);
	}
	else {
		/** Run ML-KEM-512 KAT (seeded encaps + decaps against NIST ACVP vectors). */
		Status = XAsufw_MlkemOperationKat(AsuDmaPtr);
		if (Status == XASUFW_SUCCESS) {
			/** On ML-KEM KAT success, mark ML-KEM module KAT as passed in RTCA area. */
			XASUFW_SET_KAT_PASSED(XASU_MODULE_MLKEM_ID);
		}
	}
#endif /* XASU_MLKEM_ENABLE */

#ifdef XASU_SLHDSA_ENABLE
	/** Activate SLH-DSA overlay before running SLH-DSA KAT. */
	Status = XOverlay_Activate(XOVERLAY_ALGO_SLHDSA, AsuDmaPtr);
	if (Status != XASUFW_SUCCESS) {
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_SLHDSA_ID);
		XAsufw_DisableResource(XASUFW_SLHDSA);
	} else {
		/** Run SLH-DSA keyGen KAT with ACVP SHAKE-256s vectors. */
		Status = XAsufw_SlhdsaOperationKat(AsuDmaPtr);
		if (Status == XASUFW_SUCCESS) {
			/** On SLH-DSA KAT success, mark SLH-DSA module KAT as passed
			 *  in RTCA area. */
			XASUFW_SET_KAT_PASSED(XASU_MODULE_SLHDSA_ID);
		}
	}
#endif /* XASU_SLHDSA_ENABLE */

	XAsufw_RMW(XASU_RTCA_EXEC_STATUS_ADDR, XASU_RTCA_KAT_EXEC_STATUS_MASK,
			XASU_RTCA_KAT_EXEC_STATUS_VALUE);
	XAsufw_Printf(DEBUG_GENERAL, "KATs execution completed.\r\n");

}

/*************************************************************************************************/
/**
 * @brief	This function runs SHA KAT on the given SHA instance for specified mode.
 *		On failure, marks the SHA module KAT as failed and disables the SHA resource.
 *
 * @param	XAsufw_ShaInstance	Pointer to the SHA instance.
 * @param	AsuDmaPtr		ASU DMA instance pointer.
 * @param	ShaResource		SHA2/SHA3 resource.
 * @param	ShaMode			SHA mode (256/512).
 *
 * @return
 *	- XASUFW_SUCCESS, if SHA KAT is successful.
 *	- XASUFW_SHA_HASH_COMPARISON_FAILED, if expected and generated hash comparison fails.
 *	- XASUFW_SHA_KAT_FAILED, if XAsufw_ShaKat API fails.
 *	- XASUFW_FAILURE, if any other failure.
 *
 *************************************************************************************************/
s32 XAsufw_ShaKat(XSha *XAsufw_ShaInstance, XAsufw_Dma *AsuDmaPtr, XAsufw_Resource ShaResource,
	u32 ShaMode)
{
	s32 Status = XASUFW_FAILURE;
	s32 SStatus = XASUFW_FAILURE;
	u8 OutVal[XASU_SHA_512_HASH_LEN] = {0};
	u32 HashLen = 0U;
	const u8 *ExpHash = NULL;

	/** Determine expected hash based on mode and resource. */
	switch (ShaMode) {
		case XASU_SHA_MODE_256:
			ExpHash = (ShaResource == XASUFW_SHA2) ? ExpSha2_256Hash : ExpSha3_256Hash;
			HashLen = XASU_SHA_SHAKE_256_HASH_LEN;
			break;
		case XASU_SHA_MODE_512:
			ExpHash = ExpSha2_512Hash;
			HashLen = XASU_SHA_512_HASH_LEN;
			break;
		default:
			Status = XASUFW_SHA_INVALID_SHA_MODE;
			goto END;
	}

	/** Perform SHA start operation. */
	Status = XSha_Start(XAsufw_ShaInstance, ShaMode);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	/** Perform SHA update operation. */
	Status = XSha_Update(XAsufw_ShaInstance, AsuDmaPtr, (UINTPTR)KatMessage,
		XASUFW_KAT_MSG_LENGTH_IN_BYTES, XASU_TRUE);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	/** Perform SHA finish operation. */
	Status = XSha_Finish(XAsufw_ShaInstance, AsuDmaPtr, (u64)(UINTPTR)OutVal, HashLen, XASU_FALSE);
	if (Status != XASUFW_SUCCESS) {
		goto END_CLR;
	}

	/** Compare generated hash with expected hash. */
	Status = Xil_SMemCmp(OutVal, HashLen, ExpHash, HashLen, HashLen);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_SHA_HASH_COMPARISON_FAILED;
	}

END_CLR:
	/** Securely zeroize output buffer. */
	SStatus = Xil_SMemSet(&OutVal[0U], HashLen, 0U, HashLen);
	if (Status == XASUFW_SUCCESS) {
		Status = SStatus;
	}

END:
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_SHA_KAT_FAILED);
		/**
		 * On SHA KAT failure, mark SHA module KAT as failed in RTCA area and disable
		 * the SHA resource.
		 */
		if (ShaResource == XASUFW_SHA2) {
			XASUFW_MARK_KAT_FAILED(XASU_MODULE_SHA2_ID);
		}
		else {
			XASUFW_MARK_KAT_FAILED(XASU_MODULE_SHA3_ID);
		}
		XAsufw_DisableResource(ShaResource);
	}

	return Status;
}

#ifdef XASU_RSA_PADDING_ENABLE
/*************************************************************************************************/
/**
 * @brief	This function runs RSA-OAEP KAT for encryption and decryption using 2048 bit key
 * 		and SHA2-256. On failure, marks the RSA module KAT as failed and disables the
 *		RSA resource.
 *
 * @param	AsuDmaPtr	Pointer to the ASU DMA instance.
 *
 * @return
 *	- XASUFW_SUCCESS, if RSA OAEP KAT is successful.
 *	- XASUFW_MEM_COPY_FAIL, if copying of data fails.
 * 	- XASUFW_RSA_OAEP_ENCODE_ERROR, if OAEP encode operation fails.
 * 	- XASUFW_RSA_OAEP_DECODE_ERROR, if OAEP decode operation fails.
 * 	- XASUFW_RSA_KAT_FAILED, if XAsufw_RsaEncDecOaepOpKat API fails.
 * 	- XASUFW_FAILURE, if any other failure.
 *
 *************************************************************************************************/
s32 XAsufw_RsaEncDecOaepOpKat(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_FAILURE;
	s32 SStatus = XASUFW_FAILURE;
	u32 RsaOaepOutLen = 0U;
	XAsu_RsaOaepPaddingParams RsaOaepPaddingParam;
	XAsu_RsaPvtKeyComp PvtKeyParam;
	XSha *Sha2Ptr = XSha_GetInstance(XASU_XSHA_0_DEVICE_ID);

	PvtKeyParam.PubKeyComp.Keysize = XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES;
	PvtKeyParam.PubKeyComp.PubExp = RsaPublicExp;

	Status = Xil_SMemCpy(PvtKeyParam.PubKeyComp.Modulus, XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES, RsaModulus,
		XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES, XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_MEM_COPY_FAIL;
		goto END;
	}

	PvtKeyParam.PrimeCompOrTotientPrsnt = 0U;

	Status = Xil_SMemCpy(PvtKeyParam.PvtExp, XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES, RsaPvtExp,
		XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES, XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_MEM_COPY_FAIL;
		goto END;
	}

	RsaOaepPaddingParam.XAsu_RsaOpComp.InputDataAddr = (u64)(UINTPTR)RsaData;
	RsaOaepPaddingParam.XAsu_RsaOpComp.OutputDataAddr = (u64)(UINTPTR)OutputVal;
	RsaOaepPaddingParam.XAsu_RsaOpComp.Len = XASUFW_RSA_INPUT_LEN_IN_BYTES;
	RsaOaepPaddingParam.XAsu_RsaOpComp.KeySize = XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES;
	RsaOaepPaddingParam.XAsu_RsaOpComp.KeyCompAddr = (u64)(UINTPTR)&PvtKeyParam.PubKeyComp;
	RsaOaepPaddingParam.XAsu_RsaOpComp.ExpoCompAddr = 0U;
	RsaOaepPaddingParam.ShaType = XASU_SHA2_TYPE;
	RsaOaepPaddingParam.ShaMode = XASU_SHA_MODE_256;
	RsaOaepPaddingParam.OptionalLabelAddr = (u64)(UINTPTR)RsaOpt;
	RsaOaepPaddingParam.OptionalLabelSize = XASUFW_RSA_OPTIONAL_DATA_SIZE_IN_BYTES;
	RsaOaepPaddingParam.XAsu_RsaOpComp.KeyId = 0U;
	RsaOaepPaddingParam.XAsu_RsaOpComp.OutputDataLen = XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES;

	Status = XRsa_OaepEncode(AsuDmaPtr, Sha2Ptr, &RsaOaepPaddingParam,
				RsaOaepPaddingParam.XAsu_RsaOpComp.KeyCompAddr, &RsaOaepOutLen);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_RSA_OAEP_ENCODE_ERROR;
		goto END;
	}

	if (RsaOaepOutLen != XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES) {
		Status = XASUFW_RSA_INVALID_OUTPUT_BUF_LEN;
		goto END;
	}

	RsaOaepPaddingParam.XAsu_RsaOpComp.KeyCompAddr =  (u64)(UINTPTR)&PvtKeyParam;
	RsaOaepPaddingParam.XAsu_RsaOpComp.Len = XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES;
	RsaOaepPaddingParam.XAsu_RsaOpComp.InputDataAddr = (u64)(UINTPTR)OutputVal;
	RsaOaepPaddingParam.XAsu_RsaOpComp.OutputDataAddr = (u64)(UINTPTR)&OutputVal[XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES];

	Status = XRsa_OaepDecode(AsuDmaPtr, Sha2Ptr, &RsaOaepPaddingParam,
				RsaOaepPaddingParam.XAsu_RsaOpComp.KeyCompAddr, &RsaOaepOutLen);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_RSA_OAEP_DECODE_ERROR;
		goto END;
	}

	if (RsaOaepOutLen != XASUFW_RSA_INPUT_LEN_IN_BYTES) {
		Status = XASUFW_RSA_INVALID_OUTPUT_BUF_LEN;
		goto END;
	}

	Status = Xil_SMemCmp_CT(RsaData, XASUFW_RSA_INPUT_LEN_IN_BYTES,
		(u8 *)(UINTPTR)RsaOaepPaddingParam.XAsu_RsaOpComp.OutputDataAddr,
		XASUFW_KEYWRAP_OUTPUT_SIZE_IN_BYTES, RsaOaepOutLen);

END:
	/** Zeroize local copy of output value. */
	SStatus = Xil_SMemSet(&OutputVal[0U], XASUFW_KEYWRAP_OUTPUT_SIZE_IN_BYTES, 0U,
		XASUFW_KEYWRAP_OUTPUT_SIZE_IN_BYTES);
	if (Status == XASUFW_SUCCESS) {
		Status = SStatus;
	}
	else {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_RSA_KAT_FAILED);
		/**
		 * On RSA OAEP KAT failure, mark RSA module KAT as failed in RTCA area and disable
		 * the RSA resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_RSA_ID);
		XAsufw_DisableResource(XASUFW_RSA);
	}

	return Status;
}

/*************************************************************************************************/
/**
 * @brief	This function runs RSA-PSS KAT for sign generation and verification using
 * 		2048 bit key and SHA2-256. On failure, marks the RSA module KAT as failed and
 *		disables the RSA resource.
 *
 * @param	AsuDmaPtr	Pointer to the ASU DMA instance.
 *
 * @return
 *	- XASUFW_SUCCESS, if RSA PSS signature generation and verification KAT is successful.
 *	- XASUFW_MEM_COPY_FAIL, if copying of data fails.
 * 	- XASUFW_RSA_PSS_SIGN_GEN_ERROR, if PSS sign generation operation fails.
 * 	- XASUFW_RSA_PSS_SIGN_VER_ERROR, if PSS sign verification operation fails.
 * 	- XASUFW_RSA_KAT_FAILED, if XAsufw_RsaPssSignGenAndVerifOpKat API fails.
 * 	- XASUFW_FAILURE, if any other failure.
 *
 *************************************************************************************************/
s32 XAsufw_RsaPssSignGenAndVerifOpKat(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_FAILURE;
	s32 SStatus = XASUFW_FAILURE;
	XAsu_RsaPaddingParams RsaPaddingParam;
	XAsu_RsaPvtKeyComp PvtKeyParam;
	XSha *Sha2Ptr = XSha_GetInstance(XASU_XSHA_0_DEVICE_ID);
	u32 RsaPssOutLen = 0U;

	PvtKeyParam.PubKeyComp.Keysize = XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES;
	PvtKeyParam.PubKeyComp.PubExp = RsaPublicExp;

	Status = Xil_SMemCpy(PvtKeyParam.PubKeyComp.Modulus, XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES, RsaModulus,
		    XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES, XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_MEM_COPY_FAIL;
		goto END;
	}

	PvtKeyParam.PrimeCompOrTotientPrsnt = 0U;

	Status = Xil_SMemCpy(PvtKeyParam.PvtExp, XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES, RsaPvtExp,
		    XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES, XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_MEM_COPY_FAIL;
		goto END;
	}

	RsaPaddingParam.XAsu_RsaOpComp.KeySize = XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES;
	RsaPaddingParam.XAsu_RsaOpComp.KeyCompAddr = (u64)(UINTPTR)&PvtKeyParam;
	RsaPaddingParam.XAsu_RsaOpComp.ExpoCompAddr = 0U;
	RsaPaddingParam.SaltLen = 0U;
	RsaPaddingParam.InputDataType = 0U;
	RsaPaddingParam.SignatureLen = XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES;
	RsaPaddingParam.SignatureDataAddr = 0U;
	RsaPaddingParam.ShaType = XASU_SHA2_TYPE;
	RsaPaddingParam.ShaMode = XASU_SHA_MODE_256;
	RsaPaddingParam.XAsu_RsaOpComp.InputDataAddr = (u64)(UINTPTR)RsaData;
	RsaPaddingParam.XAsu_RsaOpComp.Len = XASUFW_RSA_INPUT_LEN_IN_BYTES;
	RsaPaddingParam.XAsu_RsaOpComp.OutputDataAddr = (u64)(UINTPTR)OutputVal;
	RsaPaddingParam.XAsu_RsaOpComp.KeyId = 0U;
	RsaPaddingParam.XAsu_RsaOpComp.OutputDataLen = XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES;

	Status = XRsa_PssSignGenerate(AsuDmaPtr, Sha2Ptr, &RsaPaddingParam,
					RsaPaddingParam.XAsu_RsaOpComp.KeyCompAddr,
					&RsaPssOutLen);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_RSA_PSS_SIGN_GEN_ERROR;
		goto END;
	}

	if (RsaPssOutLen != XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES) {
		Status = XASUFW_RSA_INVALID_OUTPUT_BUF_LEN;
		goto END;
	}

	RsaPaddingParam.XAsu_RsaOpComp.OutputDataAddr = 0U;
	RsaPaddingParam.XAsu_RsaOpComp.KeyCompAddr = (u64)(UINTPTR)&PvtKeyParam.PubKeyComp;
	RsaPaddingParam.SignatureDataAddr = (u64)(UINTPTR)OutputVal;

	Status = XRsa_PssSignVerify(AsuDmaPtr, Sha2Ptr, &RsaPaddingParam,
					RsaPaddingParam.XAsu_RsaOpComp.KeyCompAddr);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_RSA_PSS_SIGN_VER_ERROR;
	}

END:
	/** Zeroize local copy of output value. */
	SStatus = Xil_SMemSet(&OutputVal[0U], XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES, 0U,
		XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES);
	if (Status == XASUFW_SUCCESS) {
		Status = SStatus;
	}
	else {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_RSA_KAT_FAILED);
		/**
		 * On RSA PSS KAT failure, mark RSA module KAT as failed in RTCA area and disable
		 * the RSA resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_RSA_ID);
		XAsufw_DisableResource(XASUFW_RSA);
	}

	return Status;
}
#endif

/*************************************************************************************************/
/**
 * @brief	This function runs ECC KAT on ECC core for P-256 curve. On failure, marks the
 *		ECC module KAT as failed and disables the ECC resource.
 *
 * @param	AsuDmaPtr	ASU DMA instance pointer.
 *
 * @return
 *	- XASUFW_SUCCESS, if ECC KAT is successful.
 *	- XASUFW_ECC_PUBKEY_COMPARISON_FAILED, if public key generation fails.
 *	- XASUFW_ECC_GEN_PUB_KEY_OPERATION_FAIL, if public key generation operation fails.
 *	- XASUFW_ECC_VALIDATE_PUB_KEY_OPERATION_FAIL, if public key validation operation fails.
 *	- XASUFW_ECC_GEN_SIGN_OPERATION_FAIL, if signature generation operation fails.
 *	- XASUFW_ECC_VERIFY_SIGN_OPERATION_FAIL, if signature verification operation fails.
 *	- XASUFW_ECC_SIGNATURE_COMPARISON_FAILED, if generated and expected signature
	comparison fails.
 *	- XASUFW_ECC_KAT_FAILED, if XAsufw_EccCoreKat API fails.
 *	- XASUFW_FAILURE, if any other failure.
 *
 *************************************************************************************************/
s32 XAsufw_EccCoreKat(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_FAILURE;
	s32 SStatus = XASUFW_FAILURE;
	u8 GenPubKey[XASUFW_DOUBLE_P256_SIZE_IN_BYTES];
	u8 GenSign[XASUFW_DOUBLE_P256_SIZE_IN_BYTES];
	XEcc *EccInstance = XEcc_GetInstance(XASU_XECC_0_DEVICE_ID);

	/** Generate the public key using the provided private key. */
	Status = XEcc_GeneratePublicKey(EccInstance, AsuDmaPtr, XECC_CURVE_TYPE_NIST_P256,
					XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES,
					(u64)(UINTPTR)EccPrivKey, (u64)(UINTPTR)GenPubKey);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_ECC_GEN_PUB_KEY_OPERATION_FAIL;
		goto END;
	}

	/** Compare the generated public key with expected public key. */
	Status = Xil_SMemCmp(GenPubKey, XASUFW_DOUBLE_P256_SIZE_IN_BYTES, EccExpPubKeyP256,
			     XASUFW_DOUBLE_P256_SIZE_IN_BYTES, XASUFW_DOUBLE_P256_SIZE_IN_BYTES);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_ECC_PUBKEY_COMPARISON_FAILED;
		goto END;
	}

	/** Validate the generated ECC public key. */
	Status = XEcc_ValidatePublicKey(EccInstance, AsuDmaPtr, XECC_CURVE_TYPE_NIST_P256,
					XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES,
					(u64)(UINTPTR)GenPubKey);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_ECC_VALIDATE_PUB_KEY_OPERATION_FAIL;
		goto END;
	}

	/** Generate signature using core API XEcc_GenerateSignature. */
	Status = XEcc_GenerateSignature(EccInstance, AsuDmaPtr, XECC_CURVE_TYPE_NIST_P256,
					XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES,
					(u64)(UINTPTR)EccPrivKey, EccEphemeralKey,
					(u64)(UINTPTR)EccHash, XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES,
					(u64)(UINTPTR)GenSign);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_ECC_GEN_SIGN_OPERATION_FAIL;
		goto END;
	}

	/** Compare the generated signature with the expected signature. */
	Status = Xil_SMemCmp(GenSign, XASUFW_DOUBLE_P256_SIZE_IN_BYTES, EccExpSignP256,
			     XASUFW_DOUBLE_P256_SIZE_IN_BYTES, XASUFW_DOUBLE_P256_SIZE_IN_BYTES);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_ECC_SIGNATURE_COMPARISON_FAILED;
		goto END;
	}

	/** Verify signature using core API XEcc_VerifySignature. */
	Status = XEcc_VerifySignature(EccInstance, AsuDmaPtr, XECC_CURVE_TYPE_NIST_P256,
				      XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES, (u64)(UINTPTR)GenPubKey,
				      (u64)(UINTPTR)EccHash, XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES,
				      (u64)(UINTPTR)GenSign);
	if ((Status != XASUFW_SUCCESS) || (ReturnStatus != XASUFW_ECC_SIGNATURE_VERIFIED)) {
		Status = XASUFW_ECC_VERIFY_SIGN_OPERATION_FAIL;
		goto END;
	}
	ReturnStatus = XASUFW_FAILURE;

END:
	/** Zeroize local copy of public key. */
	SStatus = Xil_SMemSet(&GenPubKey[0U], XASUFW_DOUBLE_P256_SIZE_IN_BYTES, 0U,
			      XASUFW_DOUBLE_P256_SIZE_IN_BYTES);
	if (Status == XASUFW_SUCCESS) {
		Status = SStatus;
	}

	/** Zeroize local copy of generated signature. */
	SStatus = Xil_SMemSet(&GenSign[0U], XASUFW_DOUBLE_P256_SIZE_IN_BYTES, 0U,
			      XASUFW_DOUBLE_P256_SIZE_IN_BYTES);
	if (Status == XASUFW_SUCCESS) {
		Status = SStatus;
	}

	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_ECC_KAT_FAILED);
		/**
		 * On ECC core KAT failure, mark ECC module KAT as failed in RTCA area and disable
		 * the ECC resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_ECC_ID);
		XAsufw_DisableResource(XASUFW_ECC);
	}

	return Status;
}

/*************************************************************************************************/
/**
 * @brief	This function runs ECC KAT on RSA core for user specified curve. On failure,
 *		marks the RSA module KAT as failed and disables the RSA resource.
 *
 * @param	AsuDmaPtr	ASU DMA instance pointer.
 * @param	CurveType	Type of elliptic curve specified by user.
 *
 * @return
 *	- XASUFW_SUCCESS, if ECC KAT is successful.
 *	- XASUFW_RSA_ECC_PUBKEY_COMPARISON_FAILED, if public key generation fails.
 *	- XASUFW_RSA_ECC_SIGNATURE_COMPARISON_FAILED, if generated and expected signature
 *	  comparison fails.
 *	- XASUFW_ECC_GEN_PUB_KEY_OPERATION_FAIL, if public key generation operation fails.
 *	- XASUFW_ECC_VALIDATE_PUB_KEY_OPERATION_FAIL, if public key validation operation fails.
 *	- XASUFW_ECC_GEN_SIGN_OPERATION_FAIL, if signature generation operation fails.
 *	- XASUFW_ECC_VERIFY_SIGN_OPERATION_FAIL, if signature verification operation fails.
 *	- XASUFW_RSA_ECC_KAT_FAILED, if XAsufw_RsaEccKat API fails.
 *	- XASUFW_FAILURE, if any other failure.
 *
 *************************************************************************************************/
s32 XAsufw_RsaEccKat(XAsufw_Dma *AsuDmaPtr, u8 CurveType)
{
	s32 Status = XASUFW_FAILURE;
	s32 SStatus = XASUFW_FAILURE;
	u8 GenPubKey[XASUFW_DOUBLE_P448_SIZE_IN_BYTES];
	u8 GenSign[XASUFW_DOUBLE_P448_SIZE_IN_BYTES];
	u8 CurveSize = 0U;
	u8 InputLen = 0U;
	const u8 *PrivateKey = NULL;
	const u8 *ExpPubKey = NULL;
	const u8 *ExpSign = NULL;

	switch (CurveType) {
		case XASU_ECC_NIST_P256:
			PrivateKey = EccPrivKey;
			ExpPubKey = EccExpPubKeyP256;
			ExpSign = EccExpSignP256;
			CurveSize = XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES;
			InputLen = XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES;
			break;
		case XASU_ECC_NIST_ED25519:
			PrivateKey = EccPrivKey25519;
			ExpPubKey = EccExpPubKey25519;
			ExpSign = EccExpSign25519;
			CurveSize = XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES;
			InputLen = 0U;
			break;
		case XASU_ECC_NIST_ED448:
			PrivateKey = EccPrivKey448;
			ExpPubKey = EccExpPubKeyP448;
			ExpSign = EccExpSignP448;
			CurveSize = XASU_ECC_ED448_PVT_KEY_SIZE_IN_BYTES;
			InputLen = 0U;
			break;

		default:
			Status = XASUFW_RSA_ECC_INVALID_PARAM;
			goto END;
	}

	/** Generate the public key using the provided private key. */
	Status = XRsa_EccGeneratePubKey(AsuDmaPtr, CurveType, CurveSize,
					(u64)(UINTPTR)PrivateKey, (u64)(UINTPTR)GenPubKey);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_ECC_GEN_PUB_KEY_OPERATION_FAIL;
		goto END;
	}

	/** Compare the generated public key with expected public key. */
	Status = Xil_SMemCmp(GenPubKey, XASUFW_DOUBLE_VALUE(CurveSize), ExpPubKey,
			     XASUFW_DOUBLE_VALUE(CurveSize), XASUFW_DOUBLE_VALUE(CurveSize));
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_RSA_ECC_PUBKEY_COMPARISON_FAILED;
		goto END;
	}

	/** Validate the generated ECC public key. */
	Status = XRsa_EccValidatePubKey(AsuDmaPtr, CurveType, CurveSize,
					(u64)(UINTPTR)GenPubKey);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_ECC_VALIDATE_PUB_KEY_OPERATION_FAIL;
		goto END;
	}

	/** Generate signature using RSA core API XRsa_EccGenerateSignature. */
	Status = XRsa_EccGenerateSignature(AsuDmaPtr, CurveType,
					   CurveSize, (u64)(UINTPTR)PrivateKey, EccEphemeralKey,
					   (u64)(UINTPTR)EccHash, InputLen, (u64)(UINTPTR)GenSign);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_ECC_GEN_SIGN_OPERATION_FAIL;
		goto END;
	}

	/** Compare the generated signature message with the expected. */
	Status = Xil_SMemCmp(GenSign, XASUFW_DOUBLE_VALUE(CurveSize), ExpSign,
			     XASUFW_DOUBLE_VALUE(CurveSize), XASUFW_DOUBLE_VALUE(CurveSize));
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_RSA_ECC_SIGNATURE_COMPARISON_FAILED;
		goto END;
	}

	/** Verify signature using RSA core API XRsa_EccVerifySignature. */
	Status = XRsa_EccVerifySignature(AsuDmaPtr, CurveType, CurveSize,
					 (u64)(UINTPTR)ExpPubKey, (u64)(UINTPTR)EccHash,
					 InputLen, (u64)(UINTPTR)GenSign);
	if ((Status != XASUFW_SUCCESS) || (ReturnStatus != XASUFW_ECC_SIGNATURE_VERIFIED)) {
		Status = XASUFW_ECC_VERIFY_SIGN_OPERATION_FAIL;
		goto END;
	}
	ReturnStatus = XASUFW_FAILURE;

END:
	/** Zeroize local copy of public key. */
	SStatus = Xil_SMemSet(&GenPubKey[0U], XASUFW_DOUBLE_P448_SIZE_IN_BYTES, 0U,
			      XASUFW_DOUBLE_P448_SIZE_IN_BYTES);
	if (Status == XASUFW_SUCCESS) {
		Status = SStatus;
	}

	/** Zeroize local copy of generated signature. */
	SStatus = Xil_SMemSet(&GenSign[0U], XASUFW_DOUBLE_P448_SIZE_IN_BYTES, 0U,
			      XASUFW_DOUBLE_P448_SIZE_IN_BYTES);
	if (Status == XASUFW_SUCCESS) {
		Status = SStatus;
	}

	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_RSA_ECC_KAT_FAILED);
		/**
		 * On RSA-ECC KAT failure, mark RSA module KAT as failed in RTCA area and disable
		 * the RSA resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_RSA_ID);
		XAsufw_DisableResource(XASUFW_RSA);
	}

	return Status;
}

/*************************************************************************************************/
/**
 * @brief	This function executes AES KAT using the user-specified engine mode (GCM/ECB).
 *		On failure, marks the AES module KAT as failed and disables the AES resource.
 *
 * @param	AsuDmaPtr	ASU DMA instance pointer.
 * @param	EngineMode	AES engine mode.
 *
 * @return
 *	- XASUFW_SUCCESS, if AES GCM KAT execution is successful.
 *	- XASUFW_AES_WRITE_KEY_FAILED, if Key write to AES USER key register fails.
 *	- XASUFW_AES_INIT_FAILED, if initialization of AES engine fails.
 *	- XASUFW_AES_UPDATE_FAILED, if update of data to AES engine fails.
 *	- XASUFW_AES_FINAL_FAILED, if completion of final AES operation fails.
 *	- XASUFW_AES_KAT_FAILED, if XAsufw_AesOperationKat API fails.
 *	- XASUFW_FAILURE, if any other failure.
 *
 *************************************************************************************************/
s32 XAsufw_AesOperationKat(XAsufw_Dma *AsuDmaPtr, u8 EngineMode)
{
	s32 Status = XASUFW_FAILURE;
	s32 ClearStatus = XASUFW_FAILURE;
	XAes *AesInstance = XAes_GetInstance(XASU_XAES_0_DEVICE_ID);
	XAsu_AesKeyObject KeyObject;
	const u8 *AesExpectedCt = (EngineMode == XASU_AES_GCM_MODE) ? ExpAesGcmCt : ExpAesEcbCt;
	const u8 *IvPtr = NULL;
	const u8 *TagPtr = NULL;
	u8 IvLen;
	u8 TagLen;
	u8 AesOutData[XASUFW_KAT_MSG_LENGTH_IN_BYTES] = {0};
	u8 AesTag[XASUFW_AES_TAG_LEN_IN_BYTES] = {0};

	/** Configure key object. */
	KeyObject.KeyAddress = (u64)(UINTPTR)AesKey;
	KeyObject.KeySrc = XASU_AES_USER_KEY_7;
	KeyObject.KeySize = XASU_AES_KEY_SIZE_256_BITS;
	KeyObject.KeyId = 0U;

	/** Write key to AES registers. */
	Status = XAes_WriteKey(AesInstance, AsuDmaPtr, &KeyObject);
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_AES_WRITE_KEY_FAILED);
		goto END;
	}

	/** Determine IV based on mode and operation. */
	IvPtr = (EngineMode == XASU_AES_GCM_MODE) ? AesIv : NULL;
	IvLen = (EngineMode == XASU_AES_GCM_MODE) ? XASUFW_AES_IV_LEN_IN_BYTES : 0U;

	/**
	 * Initialize the AES engine and load the provided key and IV to the AES engine for
	 * encryption operation.
	 */
	Status = XAes_Init(AesInstance, AsuDmaPtr, (u64)(UINTPTR)IvPtr,
		IvLen, EngineMode, XASU_AES_ENCRYPT_OPERATION);
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_AES_INIT_FAILED);
		goto END;
	}

	/** Process AAD, only for AES-GCM mode. */
	if (EngineMode == XASU_AES_GCM_MODE) {
		Status = XAes_Update(AesInstance, AsuDmaPtr, (u64)(UINTPTR)AesAad, 0U,
			XASUFW_AES_AAD_LEN_IN_BYTES, XASU_FALSE);
		if (Status != XASUFW_SUCCESS) {
			Status = XAsufw_UpdateErrorStatus(Status, XASUFW_AES_UPDATE_FAILED);
			goto END;
		}
	}

	/** Process input data. */
	Status = XAes_Update(AesInstance, AsuDmaPtr, (u64)(UINTPTR)KatMessage,
		(u64)(UINTPTR)AesOutData, XASUFW_KAT_MSG_LENGTH_IN_BYTES, XASU_TRUE);
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_AES_UPDATE_FAILED);
		goto END;
	}

	TagPtr = (EngineMode == XASU_AES_GCM_MODE) ? AesTag : NULL;
	TagLen = (EngineMode == XASU_AES_GCM_MODE) ? XASUFW_AES_TAG_LEN_IN_BYTES : 0U;

	/** Perform AES final operation for encryption. */
	Status = XAes_Final(AesInstance, AsuDmaPtr, (u64)(UINTPTR)TagPtr, TagLen);
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_AES_FINAL_FAILED);
		goto END;
	}

	/** Compare encrypted data with expected ciphertext data. */
	Status = Xil_SMemCmp_CT(AesExpectedCt, XASUFW_KAT_MSG_LENGTH_IN_BYTES,
		AesOutData, XASUFW_KAT_MSG_LENGTH_IN_BYTES, XASUFW_KAT_MSG_LENGTH_IN_BYTES);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	/** Compare generated GCM tag with the expected GCM tag. */
	if (EngineMode == XASU_AES_GCM_MODE) {
		Status = Xil_SMemCmp_CT(ExpAesGcmTag, TagLen, TagPtr, TagLen, TagLen);
		if (Status != XASUFW_SUCCESS) {
			goto END;
		}
	}

	/**
	 * Initialize the AES engine and load the provided key and IV to the AES engine for
	 * decryption operation.
	 */
	Status = XAes_Init(AesInstance, AsuDmaPtr, (u64)(UINTPTR)IvPtr,
		IvLen, EngineMode, XASU_AES_DECRYPT_OPERATION);
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_AES_INIT_FAILED);
		goto END;
	}

	/** Process AAD, only for AES-GCM mode. */
	if (EngineMode == XASU_AES_GCM_MODE) {
		Status = XAes_Update(AesInstance, AsuDmaPtr, (u64)(UINTPTR)AesAad, 0U,
			XASUFW_AES_AAD_LEN_IN_BYTES, XASU_FALSE);
		if (Status != XASUFW_SUCCESS) {
			Status = XAsufw_UpdateErrorStatus(Status, XASUFW_AES_UPDATE_FAILED);
			goto END;
		}
	}

	/** Process input data. */
	Status = XAes_Update(AesInstance, AsuDmaPtr, (u64)(UINTPTR)AesExpectedCt,
		(u64)(UINTPTR)AesOutData, XASUFW_KAT_MSG_LENGTH_IN_BYTES, XASU_TRUE);
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_AES_UPDATE_FAILED);
		goto END;
	}

	/** Perform AES final operation for encryption. */
	Status = XAes_Final(AesInstance, AsuDmaPtr, (u64)(UINTPTR)TagPtr, TagLen);
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_AES_FINAL_FAILED);
		goto END;
	}

	/** Compare decrypted data with expected input data. */
	Status = Xil_SMemCmp_CT(KatMessage, XASUFW_KAT_MSG_LENGTH_IN_BYTES, AesOutData,
		XASUFW_KAT_MSG_LENGTH_IN_BYTES, XASUFW_KAT_MSG_LENGTH_IN_BYTES);

END:
	/** Zeroize local copy of buffers. */
	ClearStatus = Xil_SecureZeroize((u8 *)(UINTPTR)AesOutData, XASUFW_KAT_MSG_LENGTH_IN_BYTES);
	ClearStatus |= Xil_SecureZeroize((u8 *)(UINTPTR)AesTag, XASUFW_AES_TAG_LEN_IN_BYTES);
	if (Status == XASUFW_SUCCESS) {
		Status = ClearStatus;
	}
	else {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_AES_KAT_FAILED);
		/**
		 * On AES KAT failure, mark AES module KAT as failed in RTCA area and disable
		 * the AES resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_AES_ID);
		XAsufw_DisableResource(XASUFW_AES);
	}

	/** Clear the key written to the XASU_AES_USER_KEY_0 key source. */
	Status = XAsufw_UpdateErrorStatus(Status, XAes_KeyClear(AesInstance, KeyObject.KeySrc));

	return Status;
}

#ifdef XASU_AES_CM_ENABLE
/*************************************************************************************************/
/**
 * @brief	This function executes AES DPA CM encryption and decryption KAT. On failure,
 *		marks the AES module KAT as failed and disables the AES resource.
 *
 * @param	AsuDmaPtr	ASU DMA instance pointer.
 *
 * @return
 *	- XASUFW_SUCCESS, if AES DPA CM KAT is successful.
 *	- XASUFW_AES_DPA_CM_ENC_OP_FAILED, if AES DPA CM KAT encrypt operation fails.
 *	- XASUFW_AES_DPA_CM_DEC_OP_FAILED, if AES DPA CM KAT encrypt operation fails.
 *	- XASUFW_AES_DPA_CM_KAT_CHECK_FAILED, if intermediate DPA CM check fails.
 *	- XASUFW_AES_DPA_CM_KAT_FAILED, if XAsufw_AesDpaCmKat API fails.
 *	- XASUFW_FAILURE, if any other failure.
 *
 *************************************************************************************************/
s32 XAsufw_AesDpaCmKat(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_FAILURE;
	XAes *InstancePtr = XAes_GetInstance(XASU_XAES_0_DEVICE_ID);
	u32 MaskedOutput0[XASUFW_AES_CM_LEN_IN_WORDS + XASUFW_AES_CM_LEN_IN_WORDS];
	u32 MaskedOutput1[XASUFW_AES_CM_LEN_IN_WORDS + XASUFW_AES_CM_LEN_IN_WORDS];
	u32 MaskedTag0[XASUFW_AES_CM_LEN_IN_WORDS + XASUFW_AES_CM_LEN_IN_WORDS];
	u32 MaskedTag1[XASUFW_AES_CM_LEN_IN_WORDS + XASUFW_AES_CM_LEN_IN_WORDS];

	if ((XASUFW_PLATFORM == PMC_TAP_VERSION_PLATFORM_QEMU) ||
		(XASUFW_PLATFORM == PMC_TAP_VERSION_PLATFORM_COSIM)) {
		XAsufw_Printf(DEBUG_INFO, "INFO: AES DPACM KAT is not supported on QEMU\r\n");
		Status = XASUFW_KAT_NOT_SUPPORTED_ON_QEMU;
		goto RET;
	}

	/** First encryption run: Use XASUFW_AES_CM_SPLIT_MASK_1 for masking input data and key. */
	Status = XAsufw_PrepareAndRunDpaCmOp(InstancePtr, AsuDmaPtr, MaskedOutput0, MaskedTag0,
		XASUFW_AES_CM_SPLIT_MASK_1, XASU_AES_ENCRYPT_OPERATION);
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_AES_DPA_CM_ENC_OP_FAILED);
		goto END;
	}

	/** Second encryption run: Use XASUFW_AES_CM_SPLIT_MASK_2 for masking input data and key. */
	Status = XAsufw_PrepareAndRunDpaCmOp(InstancePtr, AsuDmaPtr, MaskedOutput1, MaskedTag1,
		XASUFW_AES_CM_SPLIT_MASK_2, XASU_AES_ENCRYPT_OPERATION);
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_AES_DPA_CM_ENC_OP_FAILED);
		goto END;
	}

	/** Validate intermediate output. */
	Status = XAsufw_ValidateDpaIntermediateValues(MaskedOutput0,
		&MaskedOutput0[XASUFW_AES_CM_LEN_IN_WORDS], MaskedOutput1,
		&MaskedOutput1[XASUFW_AES_CM_LEN_IN_WORDS]);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	/** Validate intermediate tag output. */
	Status = XAsufw_ValidateDpaIntermediateValues(MaskedTag0,
		&MaskedTag0[XASUFW_AES_CM_LEN_IN_WORDS], MaskedTag1,
		&MaskedTag1[XASUFW_AES_CM_LEN_IN_WORDS]);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	/** Zeroize intermediate output buffers. */
	Status = Xil_SecureZeroize((u8 *)(UINTPTR)MaskedOutput0, XASUFW_AES_CM_MASK_BUF_WORD_LEN);
	Status |= Xil_SecureZeroize((u8 *)(UINTPTR)MaskedOutput1, XASUFW_AES_CM_MASK_BUF_WORD_LEN);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	/** First decryption run: Use XASUFW_AES_CM_SPLIT_MASK_1 for masking output data. */
	Status = XAsufw_PrepareAndRunDpaCmOp(InstancePtr, AsuDmaPtr, MaskedOutput0, MaskedTag0,
		XASUFW_AES_CM_SPLIT_MASK_1, XASU_AES_DECRYPT_OPERATION);
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_AES_DPA_CM_DEC_OP_FAILED);
		goto END;
	}

	/** Second decryption run: Use XASUFW_AES_CM_SPLIT_MASK_2 for masking output data. */
	Status = XAsufw_PrepareAndRunDpaCmOp(InstancePtr, AsuDmaPtr, MaskedOutput1, MaskedTag1,
		XASUFW_AES_CM_SPLIT_MASK_2, XASU_AES_DECRYPT_OPERATION);
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_AES_DPA_CM_DEC_OP_FAILED);
		goto END;
	}

	/** Validate intermediate output. */
	Status = XAsufw_ValidateDpaIntermediateValues(MaskedOutput0,
		&MaskedOutput0[XASUFW_AES_CM_LEN_IN_WORDS], MaskedOutput1,
		&MaskedOutput1[XASUFW_AES_CM_LEN_IN_WORDS]);

END:
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_AES_DPA_CM_KAT_FAILED);
		/**
		 * On AES DPA CM KAT failure, mark AES module KAT as failed in RTCA area and disable
		 * the AES resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_AES_ID);
		XAsufw_DisableResource(XASUFW_AES);
	}

RET:
	return Status;
}
#endif /* XASU_AES_CM_ENABLE */

#ifdef XASU_HMAC_ENABLE
/*************************************************************************************************/
/**
 * @brief	This function runs HMAC KAT on the given HMAC instance using SHA2-256. On failure,
 *		marks the HMAC module KAT as failed and disables the HMAC resource.
 *
 * @param	AsuDmaPtr		Pointer to the ASU DMA instance.
 *
 * @return
 *	- XASUFW_SUCCESS, if HMAC KAT is successful.
 *	- XASUFW_HMAC_KAT_COMPARISON_FAILED, if expected and generated HMAC comparison fails.
 *	- XASUFW_HMAC_KAT_FAILED, if XAsufw_HmacOperationKat API fails.
 *
 *************************************************************************************************/
s32 XAsufw_HmacOperationKat(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_FAILURE;
	s32 SStatus = XASUFW_FAILURE;
	XHmac *XAsufw_HmacInstance = XHmac_GetInstance();
	XSha *Sha2Ptr = XSha_GetInstance(XASU_XSHA_0_DEVICE_ID);
	u8 HmacOutput[XASU_SHA_SHAKE_256_HASH_LEN] = {0U};

	/** Perform HMAC init operation. */
	Status = XHmac_Init(XAsufw_HmacInstance, AsuDmaPtr, Sha2Ptr, (u64)(UINTPTR)EccPrivKey,
			    XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES, XASU_SHA_MODE_256,
			    XASU_SHA_SHAKE_256_HASH_LEN);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	/** Perform HMAC update operation. */
	Status = XHmac_Update(XAsufw_HmacInstance, AsuDmaPtr, (u64)(UINTPTR)KatMessage,
			      XASUFW_KAT_MSG_LENGTH_IN_BYTES, XASU_TRUE);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	/** Perform HMAC final operation. */
	Status = XHmac_Final(XAsufw_HmacInstance, AsuDmaPtr, (u32 *)HmacOutput);
	if (Status != XASUFW_SUCCESS) {
		goto END_CLR;
	}

	/** Compare generated HMAC output with expected HMAC output. */
	Status = Xil_SMemCmp(HmacOutput, XASU_SHA_SHAKE_256_HASH_LEN, ExpHmacOutput,
			     XASU_SHA_SHAKE_256_HASH_LEN,
			     XASU_SHA_SHAKE_256_HASH_LEN);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_HMAC_KAT_COMPARISON_FAILED;
	}

END_CLR:
	/** Zeroize local copy of output value. */
	SStatus = Xil_SMemSet(&HmacOutput[0U], XASU_SHA_SHAKE_256_HASH_LEN, 0U,
			      XASU_SHA_SHAKE_256_HASH_LEN);
	if (Status == XASUFW_SUCCESS) {
		Status = SStatus;
	}
END:
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_HMAC_KAT_FAILED);
		/**
		 * On HMAC KAT failure, mark HMAC module KAT as failed in RTCA area and disable
		 * the HMAC resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_HMAC_ID);
		XAsufw_DisableResource(XASUFW_HMAC);
	}

	return Status;
}
#endif /* XASU_HMAC_ENABLE */

#ifdef XASU_KDF_ENABLE
/*************************************************************************************************/
/**
 * @brief	This function runs KDF KAT using SHA2-256. On failure, marks the KDF module
 *		KAT as failed and disables the KDF resource.
 *
 * @param	AsuDmaPtr		Pointer to the ASU DMA instance.
 *
 * @return
 *	- XASUFW_SUCCESS, if KDF KAT is successful.
 *	- XASUFW_KDF_KAT_COMPARISON_FAILED, if expected and generated KDF comparison fails.
 *	- XASUFW_KDF_KAT_FAILED, if XAsufw_KdfOperationKat API fails.
 *
 *************************************************************************************************/
s32 XAsufw_KdfOperationKat(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_FAILURE;
	s32 SStatus = XASUFW_FAILURE;
	XSha *Sha2Ptr = XSha_GetInstance(XASU_XSHA_0_DEVICE_ID);
	u8 KdfOutput[XASU_SHA_SHAKE_256_HASH_LEN] = {0U};
	XAsu_KdfParams Params;

	Params.KeyObject.KeyInAddr = (u64)(UINTPTR)EccPrivKey;
	Params.KeyObject.KeyInLen = XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES;
	Params.KeyObject.KeyId = 0U;
	Params.ContextAddr = (u64)(UINTPTR)KatMessage;
	Params.ContextLen = XASUFW_KAT_MSG_LENGTH_IN_BYTES;
	Params.KeyOutAddr = (u64)(UINTPTR)KdfOutput;
	Params.KeyOutLen = XASU_SHA_SHAKE_256_HASH_LEN;
	Params.ShaMode = XASU_SHA_MODE_256;
	Params.ShaType = XASU_SHA2_TYPE;

	/** Perform KDF generate with known inputs. */
	Status = XKdf_Generate(AsuDmaPtr, Sha2Ptr, &Params);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	/** Compare generated KDF key output with expected KDF key output. */
	Status = Xil_SMemCmp(KdfOutput, XASU_SHA_SHAKE_256_HASH_LEN, ExpKdfOutput,
			     XASU_SHA_SHAKE_256_HASH_LEN,
			     XASU_SHA_SHAKE_256_HASH_LEN);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_KDF_KAT_COMPARISON_FAILED;
	}

END:
	/** Zeroize local copy of output value. */
	SStatus = Xil_SMemSet(&KdfOutput[0U], XASU_SHA_SHAKE_256_HASH_LEN, 0U,
			      XASU_SHA_SHAKE_256_HASH_LEN);
	Status = XAsufw_UpdateBufStatus(Status, SStatus);

	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_KDF_KAT_FAILED);
		/**
		 * On KDF KAT failure, mark KDF module KAT as failed in RTCA area and disable
		 * the KDF resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_KDF_ID);
		XAsufw_DisableResource(XASUFW_KDF);
	}

	return Status;
}
#endif /* XASU_KDF_ENABLE */

#ifdef XASU_ECIES_ENABLE
/*************************************************************************************************/
/**
 * @brief	This function runs ECIES KAT using ECC curve P-384, SHA2-256 and AES-GCM mode.
 *		On failure, marks the ECIES module KAT as failed and disables the ECIES resource.
 *
 * @param	AsuDmaPtr	Pointer to the ASU DMA instance.
 *
 * @return
 *	- XASUFW_SUCCESS, if ECIES KAT is successful.
 *	- XASUFW_ECIES_KAT_COMPARISON_FAILED, if expected and generated ECIES comparison fails.
 *	- XASUFW_ECIES_KAT_FAILED, if XAsufw_EciesOperationKat API fails.
 *
 *************************************************************************************************/
s32 XAsufw_EciesOperationKat(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_FAILURE;
	s32 SStatus = XASUFW_FAILURE;
	XSha *Sha2Ptr = XSha_GetInstance(XASU_XSHA_0_DEVICE_ID);
	XAes *AesInstancePtr = XAes_GetInstance(XASU_XAES_0_DEVICE_ID);
	XAsu_EciesParams Params;
	u8 EciesTxPubKey[XASU_ECC_P384_PVT_KEY_SIZE_IN_BYTES + XASU_ECC_P384_PVT_KEY_SIZE_IN_BYTES];
	u8 EciesMac[XASUFW_AES_TAG_LEN_IN_BYTES];
	u8 EciesEncOut[XASUFW_KAT_MSG_LENGTH_IN_BYTES];
	u8 EciesDecOut[XASUFW_KAT_MSG_LENGTH_IN_BYTES];

	Params.AesKeySize = XASU_AES_KEY_SIZE_128_BITS;
	Params.DataLength = XASUFW_KAT_MSG_LENGTH_IN_BYTES;
	Params.EccCurveType = XASU_ECC_NIST_P384;
	Params.EccKeyLength = XASU_ECC_P384_PVT_KEY_SIZE_IN_BYTES;
	Params.InDataAddr = (u64)(UINTPTR)KatMessage;
	Params.IvAddr = (u64)(UINTPTR)EciesIv;
	Params.IvLength = XASU_AES_IV_SIZE_96BIT_IN_BYTES;
	Params.MacAddr = (u64)(UINTPTR)EciesMac;
	Params.MacLength = XASU_AES_MAX_TAG_LENGTH_IN_BYTES;
	Params.OutDataAddr = (u64)(UINTPTR)EciesEncOut;
	Params.TxKeyAddr = (u64)(UINTPTR)EciesTxPubKey;
	Params.RxKeyAddr = (u64)(UINTPTR)EciesRxPubKey;
	Params.ContextAddr = (u64)(UINTPTR)RsaData;
	Params.ContextLen = XASUFW_KAT_MSG_LENGTH_IN_BYTES;
	Params.ShaMode = XASU_SHA_MODE_256;
	Params.ShaType = XASU_SHA2_TYPE;
	Params.SaltAddr = 0U;
	Params.SaltLen = 0U;

	/** Perform ECIES encryption with known inputs. */
	Status = XEcies_Encrypt(AsuDmaPtr, Sha2Ptr, AesInstancePtr, &Params);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	Params.InDataAddr = (u64)(UINTPTR)EciesEncOut;
	Params.OutDataAddr = (u64)(UINTPTR)EciesDecOut;
	Params.RxKeyAddr = (u64)(UINTPTR)EciesRxPrivKey;

	/** Perform ECIES decryption with known inputs. */
	Status = XEcies_Decrypt(AsuDmaPtr, Sha2Ptr, AesInstancePtr, &Params);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	/** Compare generated decrypted output with input message. */
	Status = Xil_SMemCmp(EciesDecOut, XASUFW_KAT_MSG_LENGTH_IN_BYTES, KatMessage,
			     XASUFW_KAT_MSG_LENGTH_IN_BYTES,
			     XASUFW_KAT_MSG_LENGTH_IN_BYTES);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_ECIES_KAT_COMPARISON_FAILED;
		goto END;
	}

END:
	/** Zeroize local copy of output value. */
	SStatus = Xil_SMemSet(&EciesEncOut[0U], XASUFW_KAT_MSG_LENGTH_IN_BYTES, 0U,
			      XASUFW_KAT_MSG_LENGTH_IN_BYTES);
	Status = XAsufw_UpdateBufStatus(Status, SStatus);

	SStatus = Xil_SMemSet(&EciesDecOut[0U], XASUFW_KAT_MSG_LENGTH_IN_BYTES, 0U,
			      XASUFW_KAT_MSG_LENGTH_IN_BYTES);
	Status = XAsufw_UpdateBufStatus(Status, SStatus);

	SStatus = Xil_SMemSet(&EciesTxPubKey[0U], (XASU_ECC_P384_PVT_KEY_SIZE_IN_BYTES +
			      XASU_ECC_P384_PVT_KEY_SIZE_IN_BYTES), 0U,
			      (XASU_ECC_P384_PVT_KEY_SIZE_IN_BYTES +
			       XASU_ECC_P384_PVT_KEY_SIZE_IN_BYTES));
	Status = XAsufw_UpdateBufStatus(Status, SStatus);

	SStatus = Xil_SMemSet(&EciesMac[0U], XASUFW_AES_TAG_LEN_IN_BYTES, 0U,
			      XASUFW_AES_TAG_LEN_IN_BYTES);

	Status = XAsufw_UpdateBufStatus(Status, SStatus);
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_ECIES_KAT_FAILED);
		/**
		 * On ECIES KAT failure, mark ECIES module KAT as failed in RTCA area and disable
		 * the ECIES resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_ECIES_ID);
		XAsufw_DisableResource(XASUFW_ECIES);
	}
	else {
		/** On ECIES KAT success, mark ECIES module KAT as passed in RTCA area. */
		XASUFW_SET_KAT_PASSED(XASU_MODULE_ECIES_ID);
	}

	return Status;
}
#endif /* XASU_ECIES_ENABLE */

#ifdef XASU_KEYWRAP_ENABLE
/*************************************************************************************************/
/**
 * @brief	This function runs key wrap unwrap KAT using SHA2-256. On failure, marks the
 *		Keywrap module KAT as failed and disables the Keywrap resource.
 *
 * @param	AsuDmaPtr	ASU DMA instance pointer.
 *
 * @return
 *	- XASUFW_SUCCESS, if Key wrap unwrap KAT is successful.
 *	- XASUFW_KEYWRAP_UNWRAPPED_DATA_COMPARISON_FAILED, if expected and generated unwrapped message
 *	comparison fails.
 *	- XASUFW_KEYWRAP_KAT_FAILED, if XAsufw_KeyWrapOperationKat API fails.
 *	- XASUFW_FAILURE, if any other failure.
 *
 *************************************************************************************************/
s32 XAsufw_KeyWrapOperationKat(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_FAILURE;
	s32 SStatus = XASUFW_FAILURE;
	u32 OutLengthVal = 0U;
	XSha *Sha2Ptr = XSha_GetInstance(XASU_XSHA_0_DEVICE_ID);
	XAes *AesPtr = XAes_GetInstance(XASU_XAES_0_DEVICE_ID);
	XAsu_KeyWrapParams KwpunwpParam;
	XAsu_RsaPvtKeyComp PvtKeyParam;
	u8 UnwrappedResult[XASUFW_KEYWRAP_INPUT_SIZE_IN_BYTES];

	PvtKeyParam.PubKeyComp.Keysize = XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES;
	PvtKeyParam.PubKeyComp.PubExp = RsaPublicExp;

	/** Copy required parameters for Key wrap unwrap operation. */
	Status = Xil_SMemCpy(PvtKeyParam.PubKeyComp.Modulus,
			     XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES, RsaModulus,
			     XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES,
			     XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_MEM_COPY_FAIL;
		goto END;
	}

	PvtKeyParam.PrimeCompOrTotientPrsnt = 0U;

	Status = Xil_SMemCpy(PvtKeyParam.PvtExp, XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES, RsaPvtExp,
		    XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES, XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_MEM_COPY_FAIL;
		goto END;
	}

	KwpunwpParam.InputDataAddr = (u64)(UINTPTR)KeyWrapInput;
	KwpunwpParam.OutputDataAddr = (u64)(UINTPTR)OutputVal;
	KwpunwpParam.ExpoCompAddr = 0U;
	KwpunwpParam.KeyCompAddr = (u64)(UINTPTR)&PvtKeyParam.PubKeyComp;
	KwpunwpParam.OptionalLabelAddr = (u64)(UINTPTR)RsaOpt;
	KwpunwpParam.ActualOutputDataLenAddr = (u64)(UINTPTR)&OutLengthVal;
	KwpunwpParam.InputDataLen = XASUFW_KEYWRAP_INPUT_SIZE_IN_BYTES;
	KwpunwpParam.RsaKeySize = XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES;
	KwpunwpParam.OptionalLabelSize = XASUFW_RSA_OPTIONAL_DATA_SIZE_IN_BYTES;
	KwpunwpParam.OutputDataLen = XASUFW_KEYWRAP_OUTPUT_SIZE_IN_BYTES;
	KwpunwpParam.AesKeySize = XASU_AES_KEY_SIZE_128_BITS;
	KwpunwpParam.ShaType = XASU_SHA2_TYPE;
	KwpunwpParam.ShaMode = XASU_SHA_MODE_256;
	KwpunwpParam.AesKeyId = 0U;
	KwpunwpParam.RsaKeyId = 0U;

	/** Perform key wrap operation with known inputs. */
	Status = XKeyWrap(&KwpunwpParam, AsuDmaPtr, Sha2Ptr, AesPtr, &OutLengthVal, NULL);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_KEYWRAP_GEN_WRAPPED_KEY_OPERATION_FAIL;
		goto END;
	}

	KwpunwpParam.InputDataAddr = (u64)(UINTPTR)OutputVal;
	KwpunwpParam.OutputDataAddr = (u64)(UINTPTR)UnwrappedResult;
	KwpunwpParam.ExpoCompAddr = 0U;
	KwpunwpParam.KeyCompAddr = (u64)(UINTPTR)&PvtKeyParam;
	KwpunwpParam.OptionalLabelAddr = (u64)(UINTPTR)RsaOpt;
	KwpunwpParam.ActualOutputDataLenAddr = (u64)(UINTPTR)&OutLengthVal;
	KwpunwpParam.InputDataLen = XASUFW_KEYWRAP_OUTPUT_SIZE_IN_BYTES;
	KwpunwpParam.RsaKeySize = XASUFW_RSA_KAT_KEY_LENGTH_IN_BYTES;
	KwpunwpParam.OptionalLabelSize = XASUFW_RSA_OPTIONAL_DATA_SIZE_IN_BYTES;
	KwpunwpParam.OutputDataLen = XASUFW_KEYWRAP_INPUT_SIZE_IN_BYTES;
	KwpunwpParam.AesKeySize = XASU_AES_KEY_SIZE_128_BITS;
	KwpunwpParam.ShaType = XASU_SHA2_TYPE;
	KwpunwpParam.ShaMode = XASU_SHA_MODE_256;

	/** Perform key unwrap operation with known inputs. */
	Status = XKeyUnwrap(&KwpunwpParam, AsuDmaPtr, Sha2Ptr, AesPtr, &OutLengthVal);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_KEYWRAP_GEN_UNWRAPPED_KEY_OPERATION_FAIL;
		goto END;
	}

	/** Compare generated unwrapped message with expected input. */
	Status = Xil_SMemCmp(UnwrappedResult, XASUFW_KEYWRAP_INPUT_SIZE_IN_BYTES, KeyWrapInput,
				XASUFW_KEYWRAP_INPUT_SIZE_IN_BYTES, XASUFW_KEYWRAP_INPUT_SIZE_IN_BYTES);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_KEYWRAP_UNWRAPPED_DATA_COMPARISON_FAILED;
		goto END;
	}

END:
	/** Zeroize local copy of wrapped output value. */
	SStatus = Xil_SMemSet(&OutputVal[0U], XASUFW_KEYWRAP_OUTPUT_SIZE_IN_BYTES, 0U,
				XASUFW_KEYWRAP_OUTPUT_SIZE_IN_BYTES);
	if (Status == XASUFW_SUCCESS) {
		Status = SStatus;
	}

	/** Zeroize local copy of unwrapped output value. */
	SStatus = Xil_SMemSet(&UnwrappedResult[0U], XASUFW_KEYWRAP_INPUT_SIZE_IN_BYTES, 0U,
				XASUFW_KEYWRAP_INPUT_SIZE_IN_BYTES);
	if (Status == XASUFW_SUCCESS) {
	  Status = SStatus;
	}

	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_KEYWRAP_KAT_FAILED);
		/**
		 * On Keywrap KAT failure, mark Keywrap module KAT as failed in RTCA area and disable
		 * the Keywrap resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_KEYWRAP_ID);
		XAsufw_DisableResource(XASUFW_KEYWRAP);
	}

	return Status;
}
#endif /* XASU_KEYWRAP_ENABLE */

#ifdef XASU_LMS_ENABLE
/*************************************************************************************************/
/**
 * @brief	This function performs HSS Known Answer Test using SHAKE-256 vectors.
 *
 * @param	AsuDmaPtr	Pointer to the AsuDma instance.
 *
 * @return
 * 	- XASUFW_SUCCESS, if HSS KAT is successful.
 * 	- XASUFW_HSS_KAT_FAILED, if HSS KAT fails.
 *
 *************************************************************************************************/
s32 XAsufw_HssOperationKat(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_FAILURE;
	XSha *ShaInstPtr = XSha_GetInstance(XASU_XSHA_1_DEVICE_ID);
	XAsu_LmsHssSignVerifyParams HssParams;

	HssParams.MsgAddr = (u64)(UINTPTR)KatMessage;
	HssParams.SignatureAddr = (u64)(UINTPTR)HssKatSignature;
	HssParams.LmsHssKeyObj.PubKeyAddr = (u64)(UINTPTR)HssKatPublicKey;
	HssParams.MsgLen = XASUFW_KAT_MSG_LENGTH_IN_BYTES;
	HssParams.SignatureLen = XASUFW_HSS_KAT_SIG_SIZE;
	HssParams.LmsHssKeyObj.PubKeyLen = XASUFW_HSS_KAT_PUB_KEY_SIZE;
	HssParams.PreHashedMsg = XASU_LMS_MSG_NOT_PREHASHED;
	HssParams.ShaType = XASU_SHA3_TYPE;
	HssParams.ShaMode = XASU_SHA_MODE_SHAKE256;
	HssParams.LmsHssKeyObj.PubKeyId = 0U;

	Status = XLms_HssInit(ShaInstPtr, AsuDmaPtr, &HssParams);
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_HSS_KAT_FAILED);
		goto END;
	}

	Status = XLms_HashMessage(ShaInstPtr, AsuDmaPtr, HssParams.MsgAddr,
				HssParams.MsgLen, HssParams.ShaMode);
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_HSS_KAT_FAILED);
		goto END;
	}

	Status = XLms_HssFinish(ShaInstPtr, AsuDmaPtr, HssParams.SignatureAddr,
				HssParams.SignatureLen);

END:
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_HSS_KAT_FAILED);
		/**
		 * On HSS KAT failure, mark LMS module KAT as failed in RTCA area and disable
		 * the LMS resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_LMS_ID);
		XAsufw_DisableResource(XASUFW_LMS);
	}
	return Status;
}
#endif /* XASU_LMS_ENABLE */

#ifdef XASU_SLHDSA_ENABLE
/*************************************************************************************************/
/**
 * @brief	This function runs SLH-DSA key-generation KAT on ASU.
 *
 * @param	AsuDmaPtr	Pointer to the AsuDma instance.
 *
 * @return
 *	- XASUFW_SUCCESS, if SLH-DSA KAT is successful.
 *	- XASUFW_SLHDSA_KAT_FAILED, if SLH-DSA KAT fails.
 *	- Error code received from called functions in case of other failure from the called
 *	  function.
 *
 * @note
 *	Uses ACVP SLH-DSA-SHAKE-256s keyGen vectors (tgId=10 tcId=91) and binds the SHA3
 *	engine for SHAKE parameter sets during the test.
 *
 *************************************************************************************************/
s32 XAsufw_SlhdsaOperationKat(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_FAILURE;
	XSlhDsa_Instance *InstPtr = XSlhDsa_GetInstance();
	XSha *ShaInstPtr = XSha_GetInstance(XASU_XSHA_1_DEVICE_ID);
	u8 Sk[XASU_SLHDSA_MAX_SK_SIZE];
	u8 Pk[XASU_SLHDSA_MAX_PK_SIZE];

	/** Bind the instance to the SHAKE-256s parameter set used by the ACVP vectors. */
	Status = XSlhDsa_BindParam(InstPtr, XSLHDSA_PARAM_SET_SHAKE_256S);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	/**
	 * Attach the SHA3 engine and DMA instances to the SLH-DSA instance. SHAKE parameter
	 * sets derive every hash from SHAKE256, so the SHA3 engine must be bound before the
	 * key generation is started.
	 */
	InstPtr->ShaInst = ShaInstPtr;
	InstPtr->DmaInst = AsuDmaPtr;

	/** Generate the key pair from the deterministic ACVP SK.seed, SK.prf and PK.seed. */
	Status = XSlhDsa_KeyGenInternal(InstPtr, SlhdsaAcvpKeyGenSkSeed,
					      SlhdsaAcvpKeyGenSkPrf,
					      SlhdsaAcvpKeyGenPkSeed, Sk, Pk);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	ASSIGN_VOLATILE(Status, XASUFW_FAILURE);
	/** Compare the generated secret key with expected secret key. */
	Status = Xil_SMemCmp(Sk, XASU_SLHDSA_256S_SK_SIZE,
			     SlhdsaAcvpKeyGenExpectedSk,
			     XASU_SLHDSA_256S_SK_SIZE,
			     XASU_SLHDSA_256S_SK_SIZE);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	ASSIGN_VOLATILE(Status, XASUFW_FAILURE);
	/** Compare the generated public key with expected public key. */
	Status = Xil_SMemCmp(Pk, XASU_SLHDSA_256S_PK_SIZE,
			     SlhdsaAcvpKeyGenExpectedPk,
			     XASU_SLHDSA_256S_PK_SIZE,
			     XASU_SLHDSA_256S_PK_SIZE);

END:
	/**
	 * Clear the seeds and intermediate state retained in the SLH-DSA instance and zeroize
	 * the local key buffers, so that no key material outlives the test on any exit path.
	 */
	Status = XAsufw_UpdateBufStatus(Status, XSlhDsa_ClearSensitiveState(InstPtr));
	Status = XAsufw_UpdateBufStatus(Status, Xil_SecureZeroize(Sk, XASU_SLHDSA_256S_SK_SIZE));
	Status = XAsufw_UpdateBufStatus(Status, Xil_SecureZeroize(Pk, XASU_SLHDSA_256S_PK_SIZE));

	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_SLHDSA_KAT_FAILED);
		/**
		 * On SLH-DSA KAT failure, mark SLH-DSA module KAT as failed in RTCA area and
		 * disable the SLH-DSA resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_SLHDSA_ID);
		XAsufw_DisableResource(XASUFW_SLHDSA);
	}

	return Status;
}
#endif /* XASU_SLHDSA_ENABLE */

/*************************************************************************************************/
/**
 * @brief	This function runs ECDH KAT on RSA core for P-256 curve. On failure, marks
 *		the RSA module KAT as failed and disables the RSA resource.
 *
 * @param	AsuDmaPtr	ASU DMA instance pointer.
 *
 * @return
 * 		- XASUFW_SUCCESS, if ECDH KAT is successful.
 * 		- XASUFW_ECDH_GEN_SECRET_OPERATION_FAIL, if shared secret generation fails.
 * 		- XASUFW_ECDH_SECRET_COMPARISON_FAILED, if generated and expected shared secret
 * 		  comparison fails.
 * 		- XASUFW_ECDH_KAT_FAILED, if ECDH KAT fails.
 * 		- XASUFW_FAILURE, if any other failure happens.
 *
 *************************************************************************************************/
s32 XAsufw_P256EcdhKat(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_FAILURE;
	s32 SStatus = XASUFW_FAILURE;
	u8 SharedSecret[XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES];

	/** Generate the shared secret using the known private key and public key. */
	Status = XRsa_EcdhGenSharedSecret(AsuDmaPtr, XASU_ECC_NIST_P256,
					  XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES,
					  (u64)(UINTPTR)EcdhPrivKey,
					  (u64)(UINTPTR)EcdhPubKey1,
					  (u64)(UINTPTR)SharedSecret, 0U);
	if ((Status != XASUFW_SUCCESS) || (ReturnStatus != XASUFW_RSA_ECDH_SUCCESS)) {
		Status = XASUFW_ECDH_GEN_SECRET_OPERATION_FAIL;
		goto END_CLR;
	}
	ReturnStatus = XASUFW_FAILURE;

	/** Compare the generated shared secret with expected shared secret. */
	Status = Xil_SMemCmp(SharedSecret, XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES, EcdhExpSharedSecret,
			     XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES,
			     XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_ECDH_SECRET_COMPARISON_FAILED;
	}

END_CLR:

	/** Zeroize local copy of shared secret. */
	SStatus = Xil_SMemSet(&SharedSecret[0U], XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES, 0U,
			      XASU_ECC_P256_PVT_KEY_SIZE_IN_BYTES);
	if (Status == XASUFW_SUCCESS) {
		Status = SStatus;
	}

	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_ECDH_KAT_FAILED);
		/**
		 * On ECDH KAT failure, mark RSA module KAT as failed in RTCA area (ECDH uses the
		 * RSA core) and disable the RSA resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_RSA_ID);
		XAsufw_DisableResource(XASUFW_RSA);
	}

	return Status;
}

#ifdef XASU_MLDSA_ENABLE
/*************************************************************************************************/
/**
 * @brief	This function runs the ML-DSA-44 Known Answer Test using official NIST ACVP
 *		vectors (FIPS 204). It performs a deterministic pure signature generation and
 *		compares the SHA2-256 digest of the produced signature against the embedded
 *		expected digest, then verifies that signature against the public key of the same
 *		ACVP test case.
 *
 *		Key generation is deliberately not exercised here. It carries a pairwise
 *		consistency test internally, so every key pair handed to a client is checked as it
 *		is produced.
 *
 *		The ML-DSA overlay image must already be loaded: the boot KAT sequence activates it
 *		in XAsufw_RunCryptoKats and the runtime KAT command activates it in the ML-DSA
 *		resource handler.
 *
 * @param	AsuDmaPtr	Pointer to the ASU DMA instance.
 *
 * @return
 *	- XASUFW_SUCCESS, if the ML-DSA KAT is successful.
 *	- XASUFW_MLDSA_SIGN_FAILED, if signature generation fails.
 *	- XASUFW_PQC_KAT_DIGEST_FAILED, if digesting the produced signature fails.
 *	- XASUFW_MLDSA_KAT_COMPARISON_FAILED, if the signature digest does not match the expected
 *	  digest.
 *	- XASUFW_MLDSA_VERIFY_FAILED, if verifying the produced signature fails.
 *	  The caller folds any of these into XASUFW_MLDSA_KAT_FAILED.
 *
 *************************************************************************************************/
s32 XAsufw_MldsaOperationKat(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_FAILURE;
	s32 SStatus = XASUFW_FAILURE;
	XSha *Sha2Ptr = XSha_GetInstance(XASU_XSHA_0_DEVICE_ID);
	u8 *KatSignature = (u8 *)(UINTPTR)XASUFW_MLDSA_KAT_BUF_ADDR;
	u8 Digest[XASU_SHA_SHAKE_256_HASH_LEN];
	XAsu_MldsaSignVerifyParams SignCmd = {
		.KeyAddr = (u64)(UINTPTR)XAsufw_MldsaKatSk,
		.MsgAddr = (u64)(UINTPTR)XAsufw_MldsaKatMsg,
		.SignatureAddr = (u64)(UINTPTR)KatSignature,
		.ContextAddr = (u64)(UINTPTR)XAsufw_MldsaKatCtx,
		.KeyLen = (u32)sizeof(XAsufw_MldsaKatSk),
		.MsgLen = (u32)sizeof(XAsufw_MldsaKatMsg),
		.SignatureLen = XASU_MLDSA_44_SIGN_LEN,
		.ContextLen = (u32)sizeof(XAsufw_MldsaKatCtx),
		.ParamSet = XASU_MLDSA_44,
		.SignMode = XASU_MLDSA_SIGN_MODE_PURE,
		.Deterministic = XASU_MLDSA_DETERMINISTIC,
	};
	/* Same inputs as SignCmd, but keyed with the public key of the same ACVP test case. */
	XAsu_MldsaSignVerifyParams VerifyCmd = {
		.KeyAddr = (u64)(UINTPTR)XAsufw_MldsaKatPk,
		.MsgAddr = (u64)(UINTPTR)XAsufw_MldsaKatMsg,
		.SignatureAddr = (u64)(UINTPTR)KatSignature,
		.ContextAddr = (u64)(UINTPTR)XAsufw_MldsaKatCtx,
		.KeyLen = (u32)sizeof(XAsufw_MldsaKatPk),
		.MsgLen = (u32)sizeof(XAsufw_MldsaKatMsg),
		.SignatureLen = XASU_MLDSA_44_SIGN_LEN,
		.ContextLen = (u32)sizeof(XAsufw_MldsaKatCtx),
		.ParamSet = XASU_MLDSA_44,
		.SignMode = XASU_MLDSA_SIGN_MODE_PURE,
	};

	/**
	 * SigGen KAT: deterministic pure ML-DSA signature over the fixed message/context using the
	 * fixed ACVP private key, then compare SHA2-256(sig) to the expected digest.
	 */
	/** The KAT signs deterministically, so no explicit rnd is needed. */
	Status = XMldsa_Sign(AsuDmaPtr, Sha2Ptr, &SignCmd, NULL, 0U);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_MLDSA_SIGN_FAILED;
		goto END;
	}

	Status = XAsufw_PqcSha256Digest(AsuDmaPtr, KatSignature, XASU_MLDSA_44_SIGN_LEN, NULL, 0U,
		Digest);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_PQC_KAT_DIGEST_FAILED;
		goto END;
	}
	Status = Xil_SMemCmp_CT(Digest, XASU_SHA_SHAKE_256_HASH_LEN, XAsufw_MldsaKatExpSigDigest,
		XASU_SHA_SHAKE_256_HASH_LEN, XASU_SHA_SHAKE_256_HASH_LEN);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_MLDSA_KAT_COMPARISON_FAILED;
		goto END;
	}

	/**
	 * SigVer KAT: the signature above now matches the ACVP known answer, so verifying it with
	 * the public key of that test case is a known-answer verification.
	 */
	Status = XMldsa_Verify(AsuDmaPtr, Sha2Ptr, &VerifyCmd);
	if ((Status != XASUFW_SUCCESS) || (ReturnStatus != XASUFW_MLDSA_SIGNATURE_VERIFIED)) {
		Status = XASUFW_MLDSA_VERIFY_FAILED;
		goto END;
	}
	ReturnStatus = XASUFW_FAILURE;

END:
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_MLDSA_KAT_FAILED);
		/**
		 * On ML-DSA KAT failure, mark ML-DSA module KAT as failed in RTCA area and disable
		 * the ML-DSA resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_MLDSA_ID);
		XAsufw_DisableResource(XASUFW_MLDSA);
	}
	/** Do not leak the signature left in the shared pool. */
	SStatus = Xil_SecureZeroize(KatSignature, XASUFW_MLDSA_KAT_BUF_LEN);
	if (Status == XASUFW_SUCCESS) {
		Status = SStatus;
	}
	SStatus = Xil_SecureZeroize(Digest, XASU_SHA_SHAKE_256_HASH_LEN);
	if (Status == XASUFW_SUCCESS) {
		Status = SStatus;
	}

	return Status;
}
#endif /* XASU_MLDSA_ENABLE */

#ifdef XASU_MLKEM_ENABLE
/*************************************************************************************************/
/**
 * @brief	This function runs the ML-KEM-512 Known Answer Test using official NIST ACVP
 *		vectors (FIPS 203). It drives the same encapsulation path the ML-KEM handler uses,
 *		passing the fixed ACVP message m to XMlkem_Encaps so that it is used as the
 *		encapsulation randomness in place of TRNG bytes, and compares the SHA2-256
 *		digest of ciphertext||shared-secret against the embedded expected digest. It then
 *		decapsulates that ciphertext with the decapsulation key of the same ACVP test case
 *		and confirms the recovered shared secret matches.
 *
 *		Key generation is deliberately not exercised here. It carries a pairwise
 *		consistency test internally, so every key pair handed to a client is checked as it
 *		is produced.
 *
 *		The ML-KEM overlay image must already be loaded: the boot KAT sequence activates it
 *		in XAsufw_RunCryptoKats and the runtime KAT command activates it in the ML-KEM
 *		resource handler.
 *
 * @param	AsuDmaPtr	Pointer to the ASU DMA instance.
 *
 * @return
 *	- XASUFW_SUCCESS, if the ML-KEM KAT is successful.
 *	- XASUFW_MLKEM_ENCAPS_FAILED, if seeded encapsulation fails.
 *	- XASUFW_PQC_KAT_DIGEST_FAILED, if digesting the ciphertext and shared secret fails.
 *	- XASUFW_MLKEM_KAT_COMPARISON_FAILED, if that digest does not match the expected digest, or
 *	  if the decapsulated shared secret does not match the encapsulated one.
 *	- XASUFW_MLKEM_DECAPS_FAILED, if decapsulation fails.
 *	  The caller folds any of these into XASUFW_MLKEM_KAT_FAILED.
 *
 *************************************************************************************************/
s32 XAsufw_MlkemOperationKat(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_FAILURE;
	s32 SStatus = XASUFW_FAILURE;
	u8 *KatCt = (u8 *)(UINTPTR)XASUFW_MLKEM_KAT_BUF_ADDR;
	u8 *KatSs = KatCt + XASU_MLKEM_512_CT_LEN;
	u8 *KatDecapsSs = KatSs + XASU_MLKEM_SHARED_SECRET_LEN;
	u8 Digest[XASU_SHA_SHAKE_256_HASH_LEN];
	XAsu_MlkemEncapsDecapsParams EncapsCmd = {
		.KeyAddr = (u64)(UINTPTR)XAsufw_MlkemKatEk,
		.CtAddr = (u64)(UINTPTR)KatCt,
		.SharedSecretAddr = (u64)(UINTPTR)KatSs,
		.KeyLen = XASU_MLKEM_512_PUB_KEY_LEN,
		.CtLen = XASU_MLKEM_512_CT_LEN,
		.SharedSecretLen = XASU_MLKEM_SHARED_SECRET_LEN,
		.ParamSet = XASU_MLKEM_512,
	};
	/* Decapsulates the ciphertext produced above with the dk of the same ACVP test case. */
	XAsu_MlkemEncapsDecapsParams DecapsCmd = {
		.KeyAddr = (u64)(UINTPTR)XAsufw_MlkemKatDk,
		.CtAddr = (u64)(UINTPTR)KatCt,
		.SharedSecretAddr = (u64)(UINTPTR)KatDecapsSs,
		.KeyLen = XASU_MLKEM_512_PRIV_KEY_LEN,
		.CtLen = XASU_MLKEM_512_CT_LEN,
		.SharedSecretLen = XASU_MLKEM_SHARED_SECRET_LEN,
		.ParamSet = XASU_MLKEM_512,
	};

	/**
	 * Encaps KAT: drive the production encapsulation path with the fixed ACVP message m against
	 * the fixed ACVP encapsulation key, then compare SHA2-256(ct || ss) to the expected digest.
	 */
	Status = XMlkem_Encaps(AsuDmaPtr, &EncapsCmd, XAsufw_MlkemKatM,
		(u32)sizeof(XAsufw_MlkemKatM));
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_MLKEM_ENCAPS_FAILED;
		goto END;
	}

	Status = XAsufw_PqcSha256Digest(AsuDmaPtr, KatCt, XASU_MLKEM_512_CT_LEN, KatSs,
		XASU_MLKEM_SHARED_SECRET_LEN, Digest);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_PQC_KAT_DIGEST_FAILED;
		goto END;
	}
	Status = Xil_SMemCmp_CT(Digest, XASU_SHA_SHAKE_256_HASH_LEN, XAsufw_MlkemKatExpCtSsDigest,
		XASU_SHA_SHAKE_256_HASH_LEN, XASU_SHA_SHAKE_256_HASH_LEN);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_MLKEM_KAT_COMPARISON_FAILED;
		goto END;
	}

	/**
	 * Decaps KAT: the ciphertext and shared secret above now match the ACVP known answer, so
	 * decapsulating that ciphertext and recovering the same shared secret is a known-answer
	 * decapsulation.
	 */
	Status = XMlkem_Decaps(AsuDmaPtr, &DecapsCmd);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_MLKEM_DECAPS_FAILED;
		goto END;
	}

	Status = Xil_SMemCmp_CT(KatDecapsSs, XASU_MLKEM_SHARED_SECRET_LEN, KatSs,
		XASU_MLKEM_SHARED_SECRET_LEN, XASU_MLKEM_SHARED_SECRET_LEN);
	if (Status != XASUFW_SUCCESS) {
		Status = XASUFW_MLKEM_KAT_COMPARISON_FAILED;
	}

END:
	if (Status != XASUFW_SUCCESS) {
		Status = XAsufw_UpdateErrorStatus(Status, XASUFW_MLKEM_KAT_FAILED);
		/**
		 * On ML-KEM KAT failure, mark ML-KEM module KAT as failed in RTCA area and disable
		 * the ML-KEM resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_MLKEM_ID);
		XAsufw_DisableResource(XASUFW_MLKEM);
	}
	/** Do not leak the shared secrets left in the shared pool. */
	SStatus = Xil_SecureZeroize(KatCt, XASUFW_MLKEM_KAT_BUF_LEN);
	if (Status == XASUFW_SUCCESS) {
		Status = SStatus;
	}
	SStatus = Xil_SecureZeroize(Digest, XASU_SHA_SHAKE_256_HASH_LEN);
	if (Status == XASUFW_SUCCESS) {
		Status = SStatus;
	}

	return Status;
}
#endif /* XASU_MLKEM_ENABLE */

/*************************************************************************************************/
/**
 * @brief	This function executes the KDF and dependent module KATs, after successful
 * 		execution it sets dependent module KAT status in RTCA area and on failure
 * 		respective module will be disabled.
 *
 * @param	AsuDmaPtr	Pointer to the dma instance.
 *
 *************************************************************************************************/
static void RunKdfAndDependentKat(XAsufw_Dma *AsuDmaPtr)
{
	XSha *XAsufw_Sha2Ptr = XSha_GetInstance(XASU_XSHA_0_DEVICE_ID);

#ifdef XASU_KDF_ENABLE
	/** Run KDF with SHA2-256 KAT. */
	if (XAsufw_KdfOperationKat(AsuDmaPtr) == XASUFW_SUCCESS) {
		/** Set KAT status as passed in RTCA area. */
		XASUFW_SET_KAT_PASSED(XASU_MODULE_KDF_ID);

		/** Set KAT status as passed in RTCA area. */
		XASUFW_SET_KAT_PASSED(XASU_MODULE_HMAC_ID);

		goto RUN_SHA2_512;
	}
#endif /* XASU_KDF_ENABLE */

#ifdef XASU_HMAC_ENABLE
	/** Run HMAC with SHA2-256 KAT. */
	if (XAsufw_HmacOperationKat(AsuDmaPtr) == XASUFW_SUCCESS) {
		/** Set KAT status as passed in RTCA area. */
		XASUFW_SET_KAT_PASSED(XASU_MODULE_HMAC_ID);

		goto RUN_SHA2_512;
	}
#endif /* XASU_HMAC_ENABLE */

	/** Run SHA2-256 KAT. */
	if (XAsufw_ShaKat(XAsufw_Sha2Ptr, AsuDmaPtr, XASUFW_SHA2,
			   XASU_SHA_MODE_256) != XASUFW_SUCCESS) {
		return;
	}

RUN_SHA2_512:
	if (XAsufw_ShaKat(XAsufw_Sha2Ptr, AsuDmaPtr, XASUFW_SHA2,
			   XASU_SHA_MODE_512) == XASUFW_SUCCESS) {
		/** Set KAT status as passed in RTCA area. */
		XASUFW_SET_KAT_PASSED(XASU_MODULE_SHA2_ID);
	}
}

#ifdef XASU_AES_CM_ENABLE
/*************************************************************************************************/
/**
 * @brief	This function prepares masked inputs and runs AES DPA CM operation based on
 * 		provided encrypt/decrypt operation and compares the output with expected data.
 *
 * @param	InstancePtr	Pointer to the AES instance.
 * @param	AsuDmaPtr	Pointer to the ASU DMA instance.
 * @param	MaskedOutputPtr	Pointer to masked output buffer.
 * @param	MaskedTagPtr	Pointer to masked tag buffer.
 * @param	SplitMask	The split mask value for this run.
 * @param	OperationType	XASU_AES_ENCRYPT_OPERATION or XASU_AES_DECRYPT_OPERATION.
 *
 * @return
 *	- XASUFW_SUCCESS, if AES DPA CM KAT output comparison is successful.
 *	- XASUFW_FAILURE, if any other failure.
 *
 *************************************************************************************************/
static s32 XAsufw_PrepareAndRunDpaCmOp(XAes *InstancePtr, XAsufw_Dma *AsuDmaPtr,
	u32 *MaskedOutputPtr, u32 *MaskedTagPtr, u32 SplitMask, u8 OperationType)
{
	s32 Status = XASUFW_FAILURE;
	s32 ClearStatus = XASUFW_FAILURE;
	u32 MaskedData[XASUFW_AES_CM_MASK_BUF_WORD_LEN];
	u32 MaskedKey[XASUFW_AES_CM_MASK_BUF_WORD_LEN];
	u32 Output[XASUFW_AES_CM_LEN_IN_WORDS];
	u32 Tag[XASUFW_AES_CM_LEN_IN_WORDS];
	u32 Index;
	u32 InputDataAddr = (u32)(UINTPTR)XASUFW_CRYPTO_AUX_BUF_ADDR;

	/** Choose input data and tag based on operation type. */
	const u32 *InputDataPtr = (OperationType == XASU_AES_ENCRYPT_OPERATION) ? AesCmPt : AesCmExpCt;
	u32 *TagPtr = (OperationType == XASU_AES_ENCRYPT_OPERATION) ? MaskedTagPtr : (u32 *)(UINTPTR)AesCmExpTag;

	/** Apply mask to data and key. */
	XAsufw_ApplyMask(InputDataPtr, MaskedData, SplitMask, XASUFW_AES_CM_LEN_IN_WORDS);
	XAsufw_ApplyMask(AesCmKey, MaskedKey, SplitMask, XASUFW_AES_CM_LEN_IN_WORDS);

	/** Write raw mask into first half of input buffer. */
	for (Index = 0U; Index < XASUFW_AES_CM_LEN_IN_WORDS; Index++) {
		XAsufw_WriteReg(InputDataAddr + (Index * XASUFW_WORD_LEN_IN_BYTES), SplitMask);
	}

	/** Write masked data into second half of input buffer. */
	for (Index = 0U; Index < XASUFW_AES_CM_LEN_IN_WORDS; Index++) {
		XAsufw_WriteReg(InputDataAddr + XASUFW_AES_CM_SPLIT_ALIGNED_LENGTH +
			(Index * XASUFW_WORD_LEN_IN_BYTES), MaskedData[Index]);
	}

	/** Run the AES DPA CM operation. */
	Status = XAes_DpaCmOperation(InstancePtr, AsuDmaPtr, InputDataAddr,
		MaskedOutputPtr, TagPtr, MaskedKey, AesCmIv, OperationType, SplitMask);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	/** Unmask the output. */
	for (Index = 0U; Index < XASUFW_AES_CM_LEN_IN_WORDS; Index++) {
		Output[Index] = MaskedOutputPtr[Index] ^
			MaskedOutputPtr[XASUFW_AES_CM_LEN_IN_WORDS + Index];
	}

	ASSIGN_VOLATILE(Status, XASUFW_FAILURE);
	/** Compare the output based on operation type. */
	if (OperationType == XASU_AES_ENCRYPT_OPERATION) {
		/** Unmask the tag. */
		for (Index = 0U; Index < XASUFW_AES_CM_LEN_IN_WORDS; Index++) {
			Tag[Index] = TagPtr[Index] ^
				TagPtr[XASUFW_AES_CM_LEN_IN_WORDS + Index];
			Tag[Index] = Xil_EndianSwap32(Tag[Index]);
		}

		/** Compare encrypted output with expected ciphertext data. */
		Status = Xil_SMemCmp_CT(AesCmExpCt, XASUFW_AES_CM_DATA_LEN_IN_BYTES, Output,
			XASUFW_AES_CM_DATA_LEN_IN_BYTES, XASUFW_AES_CM_DATA_LEN_IN_BYTES);
		if (Status != XASUFW_SUCCESS) {
			goto END;
		}

		/** Compare generated tag with expected tag. */
		Status = Xil_SMemCmp_CT(AesCmExpTag, XASUFW_AES_CM_DATA_LEN_IN_BYTES, Tag,
			XASUFW_AES_CM_DATA_LEN_IN_BYTES, XASUFW_AES_CM_DATA_LEN_IN_BYTES);
	} else {
		/** Compare decrypted data with expected input data. */
		Status = Xil_SMemCmp_CT(AesCmPt, XASUFW_AES_CM_DATA_LEN_IN_BYTES, Output,
			XASUFW_AES_CM_DATA_LEN_IN_BYTES, XASUFW_AES_CM_DATA_LEN_IN_BYTES);
	}

END:
	/** Zeroize local copy of output buffer. */
	ClearStatus = Xil_SecureZeroize((u8 *)(UINTPTR)Output, XASUFW_AES_CM_DATA_LEN_IN_BYTES);
	if (Status == XASUFW_SUCCESS) {
		Status = ClearStatus;
	}

	return Status;
}

/*************************************************************************************************/
/**
 * @brief	This function performs validation checks for AES DPA CM KAT output.
 *
 * @param 	MaskedOutput0	Pointer to the masked output0 array of size 4 words.
 * @param 	MaskedOutput1	Pointer to the masked output1 array of size 4 words.
 * @param 	Mask0		Pointer to the mask0 array of size 4 words.
 * @param 	Mask1		Pointer to the mask1 array of size 4 words.
 *
 * @return
 *	- XASUFW_SUCCESS, if DPA CM checks are passed.
 *	- XASUFW_AES_DPA_CM_KAT_CHECK_FAILED, if DPA CM checks fail.
 *
 *************************************************************************************************/
static s32 XAsufw_ValidateDpaIntermediateValues(const u32 *MaskedOutput0, const u32 *MaskedOutput1,
	const u32 *Mask0, const u32 *Mask1)
{
	s32 Status = XASUFW_AES_DPA_CM_KAT_CHECK_FAILED;

	/** Check whether masked output data are zero or not. */
	if (((MaskedOutput0[XASUFW_BUFFER_INDEX_ZERO] == 0U) &&
			(MaskedOutput0[XASUFW_BUFFER_INDEX_ONE] == 0U) &&
			(MaskedOutput0[XASUFW_BUFFER_INDEX_TWO] == 0U) &&
			(MaskedOutput0[XASUFW_BUFFER_INDEX_THREE] == 0U)) ||
			((MaskedOutput1[XASUFW_BUFFER_INDEX_ZERO] == 0U) &&
			(MaskedOutput1[XASUFW_BUFFER_INDEX_ONE] == 0U) &&
			(MaskedOutput1[XASUFW_BUFFER_INDEX_TWO] == 0U) &&
			(MaskedOutput1[XASUFW_BUFFER_INDEX_THREE] == 0U)) ||
			((Mask0[XASUFW_BUFFER_INDEX_ZERO] == 0U) &&
			(Mask0[XASUFW_BUFFER_INDEX_ONE] == 0U) &&
			(Mask0[XASUFW_BUFFER_INDEX_TWO] == 0U) &&
			(Mask0[XASUFW_BUFFER_INDEX_THREE] == 0U)) ||
			((Mask1[XASUFW_BUFFER_INDEX_ZERO] == 0U) &&
			(Mask1[XASUFW_BUFFER_INDEX_ONE] == 0U) &&
			(Mask1[XASUFW_BUFFER_INDEX_TWO] == 0U) &&
			(Mask1[XASUFW_BUFFER_INDEX_THREE] == 0U))) {
		goto END;
	}

	/** Check whether masked outputs are different. */
	if ((MaskedOutput0[XASUFW_BUFFER_INDEX_ZERO] == MaskedOutput1[XASUFW_BUFFER_INDEX_ZERO]) &&
			(MaskedOutput0[XASUFW_BUFFER_INDEX_ONE] ==
			MaskedOutput1[XASUFW_BUFFER_INDEX_ONE]) &&
			(MaskedOutput0[XASUFW_BUFFER_INDEX_TWO] ==
			MaskedOutput1[XASUFW_BUFFER_INDEX_TWO]) &&
			(MaskedOutput0[XASUFW_BUFFER_INDEX_THREE] ==
			MaskedOutput1[XASUFW_BUFFER_INDEX_THREE])) {
		goto END;
	}

	/** Check whether masks are different. */
	if ((Mask0[XASUFW_BUFFER_INDEX_ZERO] == Mask1[XASUFW_BUFFER_INDEX_ZERO]) &&
			(Mask0[XASUFW_BUFFER_INDEX_ONE] == Mask1[XASUFW_BUFFER_INDEX_ONE]) &&
			(Mask0[XASUFW_BUFFER_INDEX_TWO] == Mask1[XASUFW_BUFFER_INDEX_TWO]) &&
			(Mask0[XASUFW_BUFFER_INDEX_THREE] == Mask1[XASUFW_BUFFER_INDEX_THREE])) {
		goto END;
	}

	Status = XASUFW_SUCCESS;

END:
	return Status;
}

/*************************************************************************************************/
/**
 * @brief	This function applies a mask to given data using the XOR operation.
 *
 * @param	Data		Pointer to the data array.
 * @param	MaskedData	Pointer to the array where the masked data will be stored.
 * @param	Mask		Mask value.
 * @param	Length		Length of the Data and masked data arrays.
 *
 *************************************************************************************************/
static void XAsufw_ApplyMask(const u32 *Data, u32 *MaskedData, u32 Mask, u32 Length)
{
	u32 Index;
	for (Index = 0U; Index < Length; Index++) {
		MaskedData[Index] = (Data[Index] ^ Mask);
	}
}
#endif /* XASU_AES_CM_ENABLE */

/*************************************************************************************************/
/**
 * @brief	This function runs all AES KATs.
 *
 * @param	AsuDmaPtr	Pointer to the ASU DMA instance.
 *
 *************************************************************************************************/
static void XAsufw_RunAesKats(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_FAILURE;

	/** Run AES GCM mode KAT. */
	Status = XAsufw_AesOperationKat(AsuDmaPtr, XASU_AES_GCM_MODE);
	if (Status == XASUFW_SUCCESS) {
		/** On AES GCM KAT success, run AES ECB mode KAT. */
		Status = XAsufw_AesOperationKat(AsuDmaPtr, XASU_AES_ECB_MODE);
		if (Status == XASUFW_SUCCESS) {
#ifdef XASU_AES_CM_ENABLE
			/** On AES ECB KAT success, run AES DPA countermeasure KAT. */
			Status = XAsufw_AesDpaCmKat(AsuDmaPtr);
#endif
			if ((Status == XASUFW_SUCCESS) || (Status == XASUFW_KAT_NOT_SUPPORTED_ON_QEMU)) {
				/** On AES KATs success, mark AES module KAT as passed in RTCA area. */
				XASUFW_SET_KAT_PASSED(XASU_MODULE_AES_ID);
			}
		}
	}
}

/*************************************************************************************************/
/**
 * @brief	This function runs TRNG KAT.
 *
 * @param	XAsufw_TrngPtr	Pointer to the TRNG instance.
 *
 *************************************************************************************************/
static void XAsufw_RunTrngKats(XTrng *XAsufw_TrngPtr)
{
	s32 Status = XASUFW_FAILURE;

	/** Run TRNG KAT. */
	Status = XTrng_PreOperationalSelfTests(XAsufw_TrngPtr);
	if (Status == XASUFW_SUCCESS) {
		/** On TRNG self-tests success, enable HRNG autoproc mode. */
		Status = XTrng_EnableDefaultMode(XAsufw_TrngPtr);
	}
	if (Status != XASUFW_SUCCESS) {
		/**
		 * On TRNG KAT failure, mark TRNG module KAT as failed in RTCA area and disable
		 * the TRNG resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_TRNG_ID);
		XAsufw_DisableResource(XASUFW_TRNG);
	}
	else {
		/** On TRNG KAT success, mark TRNG module KAT as passed in RTCA area. */
		XASUFW_SET_KAT_PASSED(XASU_MODULE_TRNG_ID);
	}
}

#ifdef XASU_RSA_PADDING_ENABLE
/*************************************************************************************************/
/**
 * @brief	This function runs RSA KATs.
 *
 * @param	AsuDmaPtr	Pointer to the ASU DMA instance.
 *
 *************************************************************************************************/
static void XAsufw_RunRsaKats(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_FAILURE;

	/** Run RSA OAEP encrypt and decrypt KAT. */
	Status = XAsufw_RsaEncDecOaepOpKat(AsuDmaPtr);
	if (Status == XASUFW_SUCCESS) {
		/** On RSA OAEP KAT success, run RSA PSS signature generation and verification KAT. */
		Status = XAsufw_RsaPssSignGenAndVerifOpKat(AsuDmaPtr);
		if (Status == XASUFW_SUCCESS) {
			/** On RSA PSS KAT success, mark RSA module KAT as passed in RTCA area. */
			XASUFW_SET_KAT_PASSED(XASU_MODULE_RSA_ID);
		}
	}
}

/*************************************************************************************************/
/**
 * @brief	This function runs ECC KATs on RSA core for all enabled curves.
 *
 * @param	AsuDmaPtr	Pointer to the ASU DMA instance.
 *
 * @return
 *	- XASUFW_SUCCESS, if all enabled RSA-ECC KATs are successful.
 *	- Error code returned by XAsufw_RsaEccKat on failure.
 *
 *************************************************************************************************/
static s32 XAsufw_RunRsaEccKats(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_SUCCESS;

#ifdef XASU_ECC_SUPPORT_EDWARD_P25519
	/** Run ECC sign generation and verification KAT on RSA core using ED25519 curve. */
	Status = XAsufw_RsaEccKat(AsuDmaPtr, XASU_ECC_NIST_ED25519);
#endif /* XASU_ECC_SUPPORT_EDWARD_P25519 */
	if (Status == XASUFW_SUCCESS) {
#ifdef XASU_ECC_SUPPORT_EDWARD_P448
		/** On ED25519 KAT success, run ECC KAT on RSA core using ED448 curve. */
		Status = XAsufw_RsaEccKat(AsuDmaPtr, XASU_ECC_NIST_ED448);
#endif /* XASU_ECC_SUPPORT_EDWARD_P448 */
		if (Status == XASUFW_SUCCESS) {
#ifdef XASU_ECC_SUPPORT_NIST_P256
			/** On ED448 KAT success, run ECC KAT on RSA core using P-256 curve. */
			Status = XAsufw_RsaEccKat(AsuDmaPtr, XASU_ECC_NIST_P256);
#endif /* XASU_ECC_SUPPORT_NIST_P256 */
		}
	}

	return Status;
}
#endif /* XASU_RSA_PADDING_ENABLE */

/*************************************************************************************************/
/**
 * @brief	This function runs ECC KATs.
 *
 * @param	AsuDmaPtr	Pointer to the ASU DMA instance.
 *
 *************************************************************************************************/
static void XAsufw_RunEccKats(XAsufw_Dma *AsuDmaPtr)
{
	s32 Status = XASUFW_FAILURE;

	/** Run ECC sign generation and verification KAT on ECC core for P-256 curve. */
	Status = XAsufw_EccCoreKat(AsuDmaPtr);
	if (Status == XASUFW_SUCCESS) {
		/** On ECC core KAT success, mark ECC module KAT as passed in RTCA area. */
		XASUFW_SET_KAT_PASSED(XASU_MODULE_ECC_ID);
#ifdef XASU_RSA_PADDING_ENABLE
		if (XASUFW_IS_KAT_PASSED(XASU_MODULE_RSA_ID)) {
			Status = XAsufw_RunRsaEccKats(AsuDmaPtr);
			if (Status == XASUFW_SUCCESS) {
				/** On all RSA-ECC KATs success, mark RSA module KAT as passed in RTCA area. */
				XASUFW_SET_KAT_PASSED(XASU_MODULE_RSA_ID);
			}
		}
#endif /* XASU_RSA_PADDING_ENABLE */
	}
}

/*************************************************************************************************/
/**
 * @brief	This function runs Keywrap dependent KAT checks.
 *
 *************************************************************************************************/
static void XAsufw_RunKeywrapKats(void)
{
#ifdef XASU_KEYWRAP_ENABLE
	/** Check if all Keywrap dependent modules (AES, SHA2, RSA) have passed their KATs. */
	if ((XASUFW_IS_KAT_PASSED(XASU_MODULE_AES_ID)) &&
		(XASUFW_IS_KAT_PASSED(XASU_MODULE_SHA2_ID)) &&
		(XASUFW_IS_KAT_PASSED(XASU_MODULE_RSA_ID))) {
		/** On all dependent KATs success, mark Keywrap module KAT as passed in RTCA area. */
		XASUFW_SET_KAT_PASSED(XASU_MODULE_KEYWRAP_ID);
	}
	else {
		/**
		 * On any dependent KAT failure, mark Keywrap module KAT as failed in RTCA area
		 * and disable the Keywrap resource.
		 */
		XASUFW_MARK_KAT_FAILED(XASU_MODULE_KEYWRAP_ID);
		XAsufw_DisableResource(XASUFW_KEYWRAP);
	}
#endif /* XASU_KEYWRAP_ENABLE */
}

#if defined(XASU_MLDSA_ENABLE) || defined(XASU_MLKEM_ENABLE)
/*************************************************************************************************/
/**
 * @brief	This function computes a SHA2-256 digest over one or two input segments on the ASU
 *		hardware SHA-2 engine (XSHA_0). It is used to form the hashed representation of a
 *		PQC KAT output for comparison against the embedded expected digest (permitted by
 *		FIPS 140-3 IG 10.3.A).
 *
 * @param	AsuDmaPtr	Pointer to the ASU DMA instance.
 * @param	Segment1Ptr	Pointer to the first input segment.
 * @param	Segment1Len	Length of the first segment in bytes.
 * @param	Segment2Ptr	Pointer to the optional second input segment (NULL if unused).
 * @param	Segment2Len	Length of the second segment in bytes (0 if unused).
 * @param	Digest		Pointer to the output digest buffer (XASU_SHA_SHAKE_256_HASH_LEN).
 *
 * @return
 *	- XASUFW_SUCCESS on success.
 *	- Error code from the SHA driver on failure.
 *
 *************************************************************************************************/
static s32 XAsufw_PqcSha256Digest(XAsufw_Dma *AsuDmaPtr, const u8 *Segment1Ptr, u32 Segment1Len,
	const u8 *Segment2Ptr, u32 Segment2Len, u8 *Digest)
{
	s32 Status = XASUFW_FAILURE;
	XSha *Sha2Ptr = XSha_GetInstance(XASU_XSHA_0_DEVICE_ID);

	Status = XSha_Start(Sha2Ptr, XASU_SHA_MODE_256);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	/* All PQC KAT segments are <= XASUFW_DMA_BLOCKING_SIZE, so each update is blocking. */
	Status = XSha_Update(Sha2Ptr, AsuDmaPtr, (u64)(UINTPTR)Segment1Ptr, Segment1Len,
		(Segment2Ptr == NULL) ? (u32)XASU_TRUE : (u32)XASU_FALSE);
	if (Status != XASUFW_SUCCESS) {
		goto END;
	}

	if (Segment2Ptr != NULL) {
		Status = XSha_Update(Sha2Ptr, AsuDmaPtr, (u64)(UINTPTR)Segment2Ptr, Segment2Len,
			(u32)XASU_TRUE);
		if (Status != XASUFW_SUCCESS) {
			goto END;
		}
	}

	Status = XSha_Finish(Sha2Ptr, AsuDmaPtr, (u64)(UINTPTR)Digest,
		XASU_SHA_SHAKE_256_HASH_LEN, XASU_FALSE);

END:
	return Status;
}
#endif /* XASU_MLDSA_ENABLE || XASU_MLKEM_ENABLE */
/** @} */
